// Original, gentle music and short sound effects; all available offline.
import { getPengaturan, updatePengaturan } from './progress.js';
import { BEAT, scheduleBar } from './zepto/music-score.js';
let audioCtx = null, masterMusicGain = null, sfxGain = null;
let started = false, timer = null, nextBar = 0, bar = 0;
const narrators = new Set();
export function getMusicVolume() {
  const value = getPengaturan().volumeMusik;
  return Number.isFinite(value) ? Math.min(100, Math.max(0, value)) : 35;
}
function ctxSiap() {
  if (!audioCtx) {
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (!Audio) return null;
    audioCtx = new Audio();
  }
  if (audioCtx.state === 'suspended' && !document.hidden) audioCtx.resume().catch(() => {});
  return audioCtx;
}
function updateMusicGain() {
  if (!audioCtx || !masterMusicGain) return;
  const level = isMusicOn() ? getMusicVolume() / 100 * (narrators.size ? 0.16 : 0.7) : 0;
  masterMusicGain.gain.setTargetAtTime(level, audioCtx.currentTime, 0.15);
}
function tick() {
  if (!audioCtx || audioCtx.state !== 'running' || document.hidden) return;
  if (nextBar < audioCtx.currentTime) nextBar = audioCtx.currentTime + 0.05;
  while (nextBar < audioCtx.currentTime + 0.15) {
    scheduleBar(audioCtx, masterMusicGain, bar++, nextBar);
    nextBar += BEAT * 4;
  }
}
function mulaiAudioEngine() {
  const ctx = ctxSiap();
  if (!ctx) return false;
  if (started) return true;
  started = true;
  masterMusicGain = ctx.createGain(); masterMusicGain.gain.value = 0;
  masterMusicGain.connect(ctx.destination);
  sfxGain = ctx.createGain(); sfxGain.gain.value = isSfxOn() ? 0.4 : 0;
  sfxGain.connect(ctx.destination);
  nextBar = ctx.currentTime + 0.08;
  updateMusicGain(); tick(); timer = setInterval(tick, 100);
  return true;
}
export function ensureMusicStarted() { mulaiAudioEngine(); }
export function setMusicOn(nyala) {
  updatePengaturan({musik:nyala}); mulaiAudioEngine(); updateMusicGain();
  window.dispatchEvent(new Event('zepto-audio-change'));
}
export function toggleMusic() { setMusicOn(!isMusicOn()); return isMusicOn(); }
export function setMusicVolume(value) {
  updatePengaturan({volumeMusik:Math.min(100,Math.max(0,Number(value) || 0))});
  mulaiAudioEngine(); updateMusicGain();
}
export function setNarrationActive(source, active) {
  if (active) narrators.add(source); else narrators.delete(source);
  updateMusicGain();
}
export function setSfxOn(nyala) {
  updatePengaturan({efekSuara:nyala});
  if (sfxGain) sfxGain.gain.value = nyala ? 0.4 : 0;
}
export function isMusicOn() { return getPengaturan().musik; }
export function isSfxOn() { return getPengaturan().efekSuara; }
document.addEventListener('visibilitychange', () => {
  if (!audioCtx) return;
  if (document.hidden) audioCtx.suspend().catch(() => {});
  else if (started) audioCtx.resume().then(tick).catch(() => {});
});
window.addEventListener('pagehide', () => { clearInterval(timer); audioCtx?.suspend().catch(() => {}); });
window.addEventListener('pageshow', event => {
  if (event.persisted && started) { clearInterval(timer); timer = setInterval(tick, 100); ctxSiap(); }
});

/**
 * Mainkan efek suara pendek & lembut.
 * @param {'benar'|'salah'|'klik'|'stempel'} jenis
 */
export function mainkanSfx(jenis) {
  if (!getPengaturan().efekSuara) return;
  if (!mulaiAudioEngine()) return;
  const ctx = ctxSiap();
  const dest = sfxGain || ctx.destination;
  const now = ctx.currentTime;

  if (jenis === 'benar') {
    // Dua nada naik pendek (ceria, tidak mengagetkan)
    [523.25, 659.25].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      gain.gain.value = 0;
      osc.connect(gain);
      gain.connect(dest);
      const t0 = now + i * 0.12;
      gain.gain.linearRampToValueAtTime(0.25, t0 + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.35);
      osc.start(t0);
      osc.stop(t0 + 0.4);
    });
  } else if (jenis === 'salah') {
    // Satu nada turun pendek & lembut (tidak menakutkan untuk anak)
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(320, now);
    osc.frequency.exponentialRampToValueAtTime(220, now + 0.3);
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(dest);
    gain.gain.linearRampToValueAtTime(0.18, now + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
    osc.start(now);
    osc.stop(now + 0.45);
  } else if (jenis === 'stempel') {
    [392, 523.25, 659.25].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = freq;
      gain.gain.value = 0;
      osc.connect(gain);
      gain.connect(dest);
      const t0 = now + i * 0.1;
      gain.gain.linearRampToValueAtTime(0.2, t0 + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.3);
      osc.start(t0);
      osc.stop(t0 + 0.35);
    });
  } else {
    // klik netral
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 440;
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(dest);
    gain.gain.linearRampToValueAtTime(0.12, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    osc.start(now);
    osc.stop(now + 0.15);
  }
}
