import {mark} from './zepto/state.js';
import { mainkanSfx } from './audio.js';

const pasanganData = [
  { planet: '☿️ Merkurius', ciri: 'Planet paling dekat Matahari' },
  { planet: '♀️ Venus', ciri: 'Planet terpanas di tata surya' },
  { planet: '🌍 Bumi', ciri: 'Satu-satunya planet berkehidupan' },
  { planet: '🔴 Mars', ciri: 'Dijuluki Planet Merah' },
  { planet: '🟠 Yupiter', ciri: 'Planet terbesar di tata surya' },
  { planet: '💍 Saturnus', ciri: 'Terkenal dengan cincin indahnya' }
];

export function initMatching(container) {
  let kartuPertama = null;
  let kartuKedua = null;
  let sedangMemeriksa = false;
  let pasanganDitemukan = 0;

  const kartuList = [];
  pasanganData.forEach((p, i) => {
    kartuList.push({ id: `p${i}`, grup: i, teks: p.planet, jenis: 'planet' });
    kartuList.push({ id: `c${i}`, grup: i, teks: p.ciri, jenis: 'ciri' });
  });
  const kartuAcak = acak(kartuList);

  render();

  function acak(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function render() {
    container.innerHTML = `
      <div class="hub-header">
        <h1>🧩 Cocokkan Planet</h1>
        <p class="hub-sub">Sentuh dua kartu untuk mencocokkan planet dengan cirinya</p>
      </div>
      <div class="match-grid" id="match-grid"></div>
      <p class="match-status" id="match-status">${pasanganDitemukan} dari ${pasanganData.length} pasangan ditemukan</p>
    `;

    const grid = container.querySelector('#match-grid');
    kartuAcak.forEach(k => {
      const el = document.createElement('button');
      el.className = 'match-card';
      el.dataset.id = k.id;
      el.innerHTML = `<span class="match-card-inner">${k.teks}</span>`;
      el.addEventListener('click', () => pilihKartu(el, k));
      grid.appendChild(el);
    });
  }

  function pilihKartu(el, data) {
    if (sedangMemeriksa || el.classList.contains('match-found') || el === kartuPertama?.el) return;

    el.classList.add('match-selected');

    if (!kartuPertama) {
      kartuPertama = { el, data };
      return;
    }

    kartuKedua = { el, data };
    sedangMemeriksa = true;

    if (kartuPertama.data.grup === kartuKedua.data.grup) {
      // Cocok!
      mainkanSfx('benar');
      setTimeout(() => {
        kartuPertama.el.classList.remove('match-selected');
        kartuKedua.el.classList.remove('match-selected');
        kartuPertama.el.classList.add('match-found');
        kartuKedua.el.classList.add('match-found');
        pasanganDitemukan++;
        if(!container.querySelector('#match-status'))return;
        container.querySelector('#match-status').textContent = `${pasanganDitemukan} dari ${pasanganData.length} pasangan ditemukan`;
        kartuPertama = null;
        kartuKedua = null;
        sedangMemeriksa = false;

        if (pasanganDitemukan === pasanganData.length) {
          setTimeout(tampilkanSelesai, 400);
        }
      }, 400);
    } else {
      mainkanSfx('salah');
      el.classList.add('match-wrong');
      kartuPertama.el.classList.add('match-wrong');
      setTimeout(() => {
        kartuPertama.el.classList.remove('match-selected', 'match-wrong');
        kartuKedua.el.classList.remove('match-selected', 'match-wrong');
        kartuPertama = null;
        kartuKedua = null;
        sedangMemeriksa = false;
      }, 700);
    }
  }

  function tampilkanSelesai() {
    if(!container.querySelector('#match-grid'))return;
    mark('games','matching',10);
    container.innerHTML = `
      <div class="hub-header">
        <h1>🧩 Cocokkan Planet</h1>
      </div>
      <div class="quiz-card quiz-result">
        <div class="quiz-score">🎉</div>
        <p class="quiz-message">Hebat! Semua pasangan berhasil ditemukan!</p>
        <div class="quiz-result-buttons">
          <button class="quiz-restart-btn" id="match-ulang">🔄 Main Lagi</button>
        </div>
      </div>
    `;
    container.querySelector('#match-ulang').addEventListener('click', () => {
      pasanganDitemukan = 0;
      kartuAcak.splice(0, kartuAcak.length, ...acak(kartuList));
      render();
    });
  }
}
