export function jumlahTotalMisi() {
  return daftarMisi.length;
}

export function initMisi(container) {
  render();

  function render() {
    const progres = getProgres();
    container.innerHTML = `
      <div class="hub-header">
        <h1>🚀 Misi Antariksa</h1>
        <p class="hub-sub">${jumlahMisiSelesai()} dari ${daftarMisi.length} misi selesai</p>
      </div>
      <div class="mission-grid">
        ${daftarMisi.map(m => kartuMisi(m, progres)).join('')}
      </div>
    `;

    daftarMisi.forEach(m => {
      const btn = container.querySelector(`[data-misi="${m.id}"]`);
      if (btn) btn.addEventListener('click', () => bukaMisi(m));
    });
  }

  function kartuMisi(m, progres) {
    const selesai = !!progres.misiSelesai[m.id];
    return `
      <button class="mission-card ${selesai ? 'mission-done' : ''}" data-misi="${m.id}">
        <span class="mission-icon">${m.ikon}</span>
        <span class="mission-title">${m.judul}</span>
        <span class="mission-status">${selesai ? '✅ Misi Selesai' : '⭐ Mulai Misi'}</span>
      </button>
    `;
  }

  function bukaMisi(m) {
    container.innerHTML = `
      <div class="mission-detail">
        <button class="mission-back" id="misi-kembali">⬅ Semua Misi</button>
        <div class="mission-detail-icon">${m.ikon}</div>
        <h2>${m.judul}</h2>
        <p class="mission-goal"><strong>Tujuan:</strong> ${m.tujuan}</p>
        <p class="mission-hint">💡 <strong>Petunjuk:</strong> ${m.petunjuk}</p>
        <p class="mission-activity">🎯 <strong>Aktivitas:</strong> ${m.aktivitas}</p>

        <div class="mission-question-box">
          <p class="mission-question">${m.pertanyaan}</p>
          <div class="mission-options">
            ${m.pilihan.map((op, i) => `<button class="mission-option" data-i="${i}">${op}</button>`).join('')}
          </div>
          <p class="mission-feedback" id="misi-feedback"></p>
        </div>
      </div>
    `;

    container.querySelector('#misi-kembali').addEventListener('click', render);

    const opsiBtns = container.querySelectorAll('.mission-option');
    opsiBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const i = Number(btn.dataset.i);
        const feedback = container.querySelector('#misi-feedback');
        opsiBtns.forEach(b => b.disabled = true);

        if (i === m.jawaban) {
          btn.classList.add('mission-correct');
          feedback.textContent = '🎉 Tepat sekali! Lencana misi berhasil didapat!';
          feedback.classList.add('mission-feedback-benar');
          const { baruSelesai } = selesaikanMisi(m.id);
          if (baruSelesai) {
            setTimeout(() => {
              tampilkanStempelAnimasi(m);
            }, 500);
          }
        } else {
          btn.classList.add('mission-salah');
          feedback.textContent = 'Belum tepat, yuk coba lagi lain waktu. Kamu tetap hebat! 💪';
          feedback.classList.add('mission-feedback-salah');
        }
      });
    });
  }

  function tampilkanStempelAnimasi(m) {
    const overlay = document.createElement('div');
    overlay.className = 'stamp-overlay';
    overlay.innerHTML = `
      <div class="stamp-badge">
        <div class="stamp-icon">${m.ikon}</div>
        <div class="stamp-text">Misi Selesai!</div>
        <div class="stamp-sub">${m.judul}</div>
      </div>
    `;
    document.body.appendChild(overlay);
    setTimeout(() => overlay.classList.add('stamp-show'), 20);
    setTimeout(() => {
      overlay.classList.remove('stamp-show');
      setTimeout(() => overlay.remove(), 400);
    }, 1800);
  }
}
