import { getPengaturan, updatePengaturan } from './progress.js';
import { setMusicOn, setSfxOn, setMusicVolume, getMusicVolume } from './audio.js';

export function initSettings(container) {
  render();

  function render() {
    const p = getPengaturan();
    container.innerHTML = `
      <div class="hub-header">
        <h1>⚙️ Pengaturan</h1>
        <p class="hub-sub">Sesuaikan pengalaman belajarmu</p>
      </div>

      <div class="settings-list">
        ${baris('musik', '🎵 Musik Latar', p.musik)}
        <div class="z-music-volume"><label for="music-volume">Volume musik <output id="music-volume-value">${getMusicVolume()}%</output></label><input id="music-volume" type="range" min="0" max="100" step="5" value="${getMusicVolume()}"><p>Melodi ceria dan lembut. Musik mengecil saat narasi dibacakan.</p></div>
        ${baris('efekSuara', '🔊 Efek Suara', p.efekSuara)}
        ${baris('narasi', '🗣️ Narasi Suara', p.narasi)}
        ${baris('kurangiAnimasi', '✨ Kurangi Animasi', p.kurangiAnimasi)}
      </div>

      <div class="settings-list">
        <div class="settings-row">
          <span class="settings-label">🖼️ Kualitas Grafis</span>
          <div class="settings-graphics-toggle">
            <button class="settings-graphics-btn ${p.grafis === 'tinggi' ? 'active' : ''}" data-grafis="tinggi">Tinggi</button>
            <button class="settings-graphics-btn ${p.grafis === 'hemat' ? 'active' : ''}" data-grafis="hemat">Hemat Baterai</button>
          </div>
        </div>
      </div>
      <section class="z-panel"><h2>Mulai belajar lagi</h2><p>Reset nilai dan progres untuk mengulang pembelajaran atau berganti siswa.</p><button class="z-btn" id="settings-reset-belajar" type="button">🔄 Reset Pembelajaran</button></section>
    `;

    container.querySelector('#music-volume').addEventListener('input', event => {
      setMusicVolume(event.target.value);
      container.querySelector('#music-volume-value').textContent = getMusicVolume() + '%';
    });
    container.querySelector('#settings-reset-belajar').onclick=()=>window.dispatchEvent(new Event('zepto-request-reset'));
    container.querySelectorAll('[data-toggle]').forEach(sw => {
      sw.addEventListener('click', () => {
        const key = sw.dataset.toggle;
        const nilaiBaru = !getPengaturan()[key];
        updatePengaturan({ [key]: nilaiBaru });
        if (key === 'musik') setMusicOn(nilaiBaru);
        if (key === 'efekSuara') setSfxOn(nilaiBaru);
        render();
      });
    });

    container.querySelectorAll('[data-grafis]').forEach(btn => {
      btn.addEventListener('click', () => {
        updatePengaturan({ grafis: btn.dataset.grafis });
        render();
      });
    });
  }

  function baris(key, label, aktif) {
    return `
      <div class="settings-row">
        <span class="settings-label">${label}</span>
        <button class="settings-switch ${aktif ? 'on' : ''}" data-toggle="${key}">
          <span class="settings-switch-knob"></span>
        </button>
      </div>
    `;
  }
}
