// Original, offline instrumental: gentle toy-piano melody, 92 BPM, C major.
export const BEAT = 60 / 92;
const CHORDS = [[48,52,55],[45,48,52],[53,57,60],[43,47,50]];
const MELODY = [
  [[0,64],[1,67],[2,69],[3,67]],
  [[0,64],[1.5,62],[2.5,60]],
  [[0,65],[1,69],[2,67],[3,65]],
  [[0,62],[1,64],[2,67]],
  [[0,67],[1,72],[2,71],[3,67]],
  [[0,69],[1.5,67],[2.5,64]],
  [[0,65],[1,64],[2,62],[3,65]],
  [[0,62],[1,67],[2,60]]
];
function note(ctx, dest, midi, time, duration, level, soft = false) {
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0, time);
  gain.gain.linearRampToValueAtTime(level, time + 0.025);
  gain.gain.exponentialRampToValueAtTime(0.0001, time + duration);
  gain.connect(dest);
  const fundamental = ctx.createOscillator();
  fundamental.type = 'sine';
  fundamental.frequency.value = 440 * 2 ** ((midi - 69) / 12);
  fundamental.connect(gain);
  fundamental.start(time); fundamental.stop(time + duration + 0.03);
  fundamental.onended = () => { fundamental.disconnect(); gain.disconnect(); };
  if (!soft) {
    const overtone = ctx.createOscillator(), overtoneGain = ctx.createGain();
    overtone.frequency.value = fundamental.frequency.value * 2;
    overtoneGain.gain.value = 0.12;
    overtone.connect(overtoneGain); overtoneGain.connect(gain);
    overtone.start(time); overtone.stop(time + duration * 0.65);
    overtone.onended = () => { overtone.disconnect(); overtoneGain.disconnect(); };
  }
}
export function scheduleBar(ctx, dest, bar, time) {
  const chord = CHORDS[bar % CHORDS.length];
  // A quiet plucked accompaniment with space between the melody phrases.
  chord.forEach((midi, i) => note(ctx, dest, midi + 12, time + i * BEAT, BEAT * 1.5, 0.045, true));
  note(ctx, dest, chord[0], time, BEAT * 2.6, 0.065, true);
  const phrase = MELODY[bar % MELODY.length];
  for (const [beat, midi] of phrase) note(ctx, dest, midi, time + beat * BEAT, BEAT * 1.25, 0.13);
}
