const KEY='zepto_v1';
const defaults=()=>({profile:null,pretest:null,posttest:null,attempt:null,read:[],explored:[],missions:[],games:[],rewards:{},stars:0,badges:[],level:'Astronaut Pemula',tutorial:false,activeMission:null,found:[]});
export function state(){try{return {...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return defaults()}}
export function level(n){return n>=250?'Master Tata Surya':n>=150?'Kapten ZEPTO':n>=75?'Penjelajah Planet':'Astronaut Pemula'}
export function save(s){
 s.level=level(s.stars);
 const badges=[];
 if(s.explored.includes('Earth'))badges.push('🌍 Penjelajah Bumi');
 if(s.explored.includes('Moon'))badges.push('🌕 Sahabat Bulan');
 if(s.explored.includes('Sun'))badges.push('☀️ Sahabat Matahari');
 if(['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'].every(x=>s.explored.includes(x)))badges.push('🪐 Ahli Planet');
 if(s.explored.includes('Comet'))badges.push('☄️ Pemburu Komet');
 if(s.missions.length===7)badges.push('🚀 Penjelajah ZEPTO');
 if(s.posttest?.score>=80)badges.push('🧠 Jago Tata Surya');
 if(s.missions.length===7&&s.games.length>=4&&s.posttest?.score>=80)badges.push('🏆 Master ZEPTO');
 s.badges=badges;
 try{localStorage.setItem(KEY,JSON.stringify(s))}catch{window.dispatchEvent(new CustomEvent('zepto-toast',{detail:'Penyimpanan penuh atau tidak tersedia. Progres belum tersimpan.'}));return false}
 window.dispatchEvent(new Event('zepto-progress'));return true;
}
export function reward(key,points,s=state()){
 if(!s.rewards[key]){s.rewards[key]=points;s.stars+=points;save(s);window.dispatchEvent(new CustomEvent('zepto-toast',{detail:`+${points} Bintang ZEPTO ⭐`}));return true}save(s);return false;
}
export function mark(group,id,points){const s=state();if(!s[group].includes(id))s[group].push(id);reward(group+':'+id,points,s)}
export function scoreAnswers(answers){const correct=answers.filter(a=>a.choice===a.correct).length;return {score:Math.round(correct/answers.length*100),correct,wrong:answers.length-correct,total:answers.length}}
export function canPost(s=state()){return !!s.pretest&&s.read.length>=1&&s.explored.length>=1}
export function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
