import {reward} from './zepto/state.js';
import { catatHasilKuis } from './progress.js';
import { mainkanSfx } from './audio.js';

// ======  BANK SOAL KUIS TATA SURYA  ======
const bankSoal = [
  { q: 'Planet apa yang paling dekat dengan Matahari?', opsi: ['Venus', 'Merkurius', 'Bumi', 'Mars'], benar: 1, bahas: 'Merkurius adalah planet pertama, paling dekat dengan Matahari.' },
  { q: 'Planet mana yang dijuluki "Planet Merah"?', opsi: ['Yupiter', 'Saturnus', 'Mars', 'Venus'], benar: 2, bahas: 'Mars terlihat kemerahan karena banyak mengandung besi oksida (karat) di permukaannya.' },
  { q: 'Apa planet terbesar di tata surya kita?', opsi: ['Saturnus', 'Uranus', 'Bumi', 'Yupiter'], benar: 3, bahas: 'Jupiter adalah planet terbesar di Tata Surya, jauh lebih besar daripada Bumi.' },
  { q: 'Planet mana yang paling terkenal karena cincinnya?', opsi: ['Saturnus', 'Neptunus', 'Merkurius', 'Mars'], benar: 0, bahas: 'Cincin Saturnus terbuat dari jutaan kepingan es dan batu.' },
  { q: 'Ada berapa planet di tata surya kita?', opsi: ['7', '8', '9', '10'], benar: 1, bahas: 'Ada 8 planet resmi: Merkurius, Venus, Bumi, Mars, Yupiter, Saturnus, Uranus, dan Neptunus.' },
  { q: 'Planet apa satu-satunya yang diketahui memiliki kehidupan?', opsi: ['Mars', 'Venus', 'Bumi', 'Yupiter'], benar: 2, bahas: 'Bumi punya air, udara, dan suhu yang pas untuk kehidupan.' },
  { q: 'Planet mana yang berputar hampir menyamping?', opsi: ['Uranus', 'Neptunus', 'Saturnus', 'Yupiter'], benar: 0, bahas: 'Uranus berputar dengan posisi sangat miring, seperti bola yang menggelinding!' },
  { q: 'Siapa nama satelit alami Bumi?', opsi: ['Titan', 'Bulan', 'Europa', 'Phobos'], benar: 1, bahas: 'Bulan adalah satu-satunya satelit alami Bumi.' },
  { q: 'Sejak 2006, Pluto diklasifikasikan sebagai apa?', opsi: ['Planet utama', 'Asteroid', 'Planet katai', 'Komet'], benar: 2, bahas: 'Pluto disebut planet katai karena ukurannya kecil dan orbitnya ramai objek lain.' },
  { q: 'Planet apa yang letaknya paling jauh dari Matahari?', opsi: ['Uranus', 'Pluto', 'Saturnus', 'Neptunus'], benar: 3, bahas: 'Neptunus adalah planet terjauh sejak Pluto tak lagi dianggap planet utama.' },
  { q: 'Berapa lama Bumi berputar mengelilingi porosnya sendiri?', opsi: ['1 jam', '24 jam', '1 minggu', '1 bulan'], benar: 1, bahas: 'Satu putaran penuh Bumi pada porosnya memakan waktu sekitar 24 jam, itulah satu hari.' },
  { q: 'Apa nama bintang pusat tata surya kita?', opsi: ['Matahari', 'Sirius', 'Bulan', 'Polaris'], benar: 0, bahas: 'Matahari adalah bintang yang menjadi pusat tata surya kita.' }
];

const KALIMAT_SEMANGAT = [
  'Belum tepat, yuk lihat petunjuknya!',
  'Hampir benar, coba lagi ya!',
  'Tidak apa-apa, kita belajar bersama!',
  'Jangan menyerah, kamu pasti bisa!'
];

/**
 * @param {HTMLElement} container
 * @param {Function} onSelesai - dipanggil saat pengguna menekan "Kembali"
 */
export function initQuiz(container, onSelesai) {
  let jumlahSoal = 5;
  let pakaiTimer = false;
  let soalTerpilih = [];
  let currentIndex = 0;
  let score = 0;
  let timerInterval = null;
  window.addEventListener('zepto-navigation',()=>clearInterval(timerInterval),{once:true});
  const DURASI_TIMER = 20; // detik per soal

  renderSetup();

  // ======  LAYAR PENGATURAN SESI  ======
  function renderSetup() {
    container.innerHTML = `
      <div class="quiz-header">
        <h1>📝 Kuis Latihan ZEPTO</h1>
        <p class="quiz-progress">Pilih pengaturan sesi kuismu</p>
      </div>
      <div class="quiz-card">
        <p class="quiz-setup-label">Jumlah soal:</p>
        <div class="quiz-setup-options">
          <button class="quiz-setup-btn active" data-jumlah="5">5 Soal</button>
          <button class="quiz-setup-btn" data-jumlah="10">10 Soal</button>
        </div>
        <p class="quiz-setup-label">Timer per soal:</p>
        <div class="quiz-setup-options">
          <button class="quiz-setup-btn active" data-timer="off">Tanpa Timer</button>
          <button class="quiz-setup-btn" data-timer="on">Dengan Timer (20 detik)</button>
        </div>
        <button class="quiz-next-btn" id="quiz-mulai">Mulai Kuis 🚀</button>
      </div>
    `;

    const jumlahBtns = container.querySelectorAll('[data-jumlah]');
    jumlahBtns.forEach(btn => btn.addEventListener('click', () => {
      jumlahBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      jumlahSoal = Number(btn.dataset.jumlah);
    }));

    const timerBtns = container.querySelectorAll('[data-timer]');
    timerBtns.forEach(btn => btn.addEventListener('click', () => {
      timerBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      pakaiTimer = btn.dataset.timer === 'on';
    }));

    container.querySelector('#quiz-mulai').addEventListener('click', mulaiKuis);
  }

  function acakArray(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function mulaiKuis() {
    soalTerpilih = acakArray(bankSoal).slice(0, jumlahSoal);
    currentIndex = 0;
    score = 0;
    renderQuestion();
  }

  function renderQuestion() {
    clearInterval(timerInterval);
    const q = soalTerpilih[currentIndex];

    container.innerHTML = `
      <div class="quiz-header">
        <h1>📝 Kuis Latihan ZEPTO</h1>
        <div class="quiz-progress">Soal ${currentIndex + 1} dari ${soalTerpilih.length} &nbsp;|&nbsp; Skor: ${score}</div>
        ${pakaiTimer ? `<div class="quiz-timer-bar"><div class="quiz-timer-fill" id="quiz-timer-fill"></div></div>` : ''}
      </div>
      <div class="quiz-card">
        <div class="quiz-question">${q.q}</div>
        <div class="quiz-options">
          ${q.opsi.map((opt, i) => `<button class="quiz-option" data-index="${i}">${opt}</button>`).join('')}
        </div>
      </div>
    `;

    const optionButtons = container.querySelectorAll('.quiz-option');
    optionButtons.forEach(btn => {
      btn.addEventListener('click', () => handleAnswer(btn, optionButtons, q));
    });

    if (pakaiTimer) {
      let sisa = DURASI_TIMER;
      const fill = container.querySelector('#quiz-timer-fill');
      if (fill) fill.style.width = '100%';
      timerInterval = setInterval(() => {
        if(!container.isConnected||!container.querySelector('#quiz-timer-fill')){clearInterval(timerInterval);return;}
        if(document.hidden)return;
        sisa -= 1;
        if (fill) fill.style.width = `${(sisa / DURASI_TIMER) * 100}%`;
        if (sisa <= 0) {
          clearInterval(timerInterval);
          handleAnswer(null, optionButtons, q); // waktu habis = tidak terjawab
        }
      }, 1000);
    }
  }

  function handleAnswer(selectedBtn, allButtons, q) {
    clearInterval(timerInterval);
    const selectedIndex = selectedBtn ? Number(selectedBtn.dataset.index) : -1;
    if(!container.isConnected||!container.closest('.active-screen')||!container.querySelector('.quiz-options'))return;
    const benar = selectedIndex === q.benar;

    if (benar) {
      score++;
      reward('quiz:'+q.q,5);
      mainkanSfx('benar');
    } else {
      mainkanSfx('salah');
    }

    allButtons.forEach(btn => {
      btn.disabled = true;
      const idx = Number(btn.dataset.index);
      if (idx === q.benar) {
        btn.classList.add('correct');
      } else if (idx === selectedIndex) {
        btn.classList.add('incorrect');
      }
    });

    const quizCard = container.querySelector('.quiz-card');

    const bahasEl = document.createElement('p');
    bahasEl.className = 'quiz-explain';
    if (!benar) {
      const semangat = KALIMAT_SEMANGAT[Math.floor(Math.random() * KALIMAT_SEMANGAT.length)];
      bahasEl.innerHTML = `<strong>${semangat}</strong><br>${q.bahas}`;
    } else {
      bahasEl.innerHTML = `<strong>Betul sekali! 🎉</strong><br>${q.bahas}`;
    }
    quizCard.appendChild(bahasEl);

    const nextBtn = document.createElement('button');
    nextBtn.className = 'quiz-next-btn';
    nextBtn.textContent = currentIndex < soalTerpilih.length - 1 ? 'Soal Berikutnya ➡' : 'Lihat Hasil 🏁';
    nextBtn.addEventListener('click', () => {
      currentIndex++;
      if (currentIndex < soalTerpilih.length) {
        renderQuestion();
      } else {
        renderResult();
      }
    });
    quizCard.appendChild(nextBtn);
  }

  function renderResult() {
    const total = soalTerpilih.length;
    reward("quiz-complete",10);
    let pesan;
    if (score === total) {
      pesan = 'Sempurna! Kamu benar-benar ahli tata surya! 🌟';
    } else if (score >= total * 0.7) {
      pesan = 'Kerja bagus! Pengetahuanmu tentang tata surya cukup luas. 🚀';
    } else if (score >= total * 0.4) {
      pesan = 'Lumayan! Coba jelajahi lagi Tata Surya untuk belajar lebih banyak. 🪐';
    } else {
      pesan = 'Jangan menyerah! Yuk jelajahi Tata Surya dulu, lalu coba lagi. ✨';
    }

    const { baru } = catatHasilKuis(score, total);
    const badgesHTML = baru.length
      ? `<div class="badges-row">${baru.map(l => `
          <div class="badge-item">
            <span class="badge-icon">${l.ikon}</span>
            <span class="badge-name">${l.nama}</span>
          </div>`).join('')}</div>`
      : '';

    container.innerHTML = `
      <div class="quiz-header">
        <h1>📝 Kuis Latihan ZEPTO</h1>
      </div>
      <div class="quiz-card quiz-result">
        <p class="quiz-message">Kuis selesai!</p>
        <div class="quiz-score">${score} / ${total}</div>
        <p class="quiz-message">${pesan}</p>
        ${badgesHTML}
        <div class="quiz-result-buttons">
          <button class="quiz-restart-btn" id="quiz-restart">🔄 Main Lagi</button>
          <button class="quiz-menu-btn" id="quiz-to-menu">🏠 Kembali</button>
        </div>
      </div>
    `;

    container.querySelector('#quiz-restart').addEventListener('click', renderSetup);
    container.querySelector('#quiz-to-menu').addEventListener('click', () => {
      if (onSelesai) onSelesai();
    });
  }
}
