import { Capacitor } from '@capacitor/core';
import { TextToSpeech } from '@capacitor-community/text-to-speech';
import { getPengaturan } from '../progress.js';
import { setNarrationActive } from '../audio.js';
let request = 0;
export async function stopVoice() {
  request++;
  setNarrationActive('lesson', false);
  if (Capacitor.isNativePlatform()) { try { await TextToSpeech.stop(); } catch {} }
  else window.speechSynthesis?.cancel();
}
export async function speak(text) {
  if (!getPengaturan().narasi) return;
  await stopVoice();
  const current = ++request;
  const done = () => { if (current === request) setNarrationActive('lesson', false); };
  setNarrationActive('lesson', true);
  try {
    if (Capacitor.isNativePlatform()) {
      await TextToSpeech.speak({text, lang:'id-ID', rate:0.85}); done();
    } else if (window.speechSynthesis) {
      const u = new SpeechSynthesisUtterance(text);
      u.lang = 'id-ID'; u.rate = 0.85; u.onend = done; u.onerror = done;
      window.speechSynthesis.speak(u);
    } else throw Error('unsupported');
  } catch {
    done();
    window.dispatchEvent(new CustomEvent('zepto-toast', {detail:'Suara belum tersedia di perangkat ini. Kamu tetap bisa membaca penjelasan.'}));
  }
}
