// ******  TOMBOL SUARA (TEXT-TO-SPEECH)  ******
// Di web browser: pakai Web Speech API (window.speechSynthesis)
// Di aplikasi Android (APK): WebView tidak mendukung speechSynthesis dengan baik,
// jadi kita pakai plugin TTS NATIVE Android (@capacitor-community/text-to-speech)
const isNativeApp = Capacitor.isNativePlatform();
let isSpeakingNative = false;
let planetVoiceRequest = 0;

async function speakPlanetInfo() {
  if (!currentPlanetKey) return;

  const data = planetData[currentPlanetKey];
  const namaID = planetNameID[currentPlanetKey] || currentPlanetKey;
  const teks = zObjects.find(x=>x.id===currentPlanetKey)?.text || data.info;

  const speakBtn = document.getElementById('speak-btn');

  const voiceRequest = ++planetVoiceRequest;
  const finishVoice = () => { if (voiceRequest === planetVoiceRequest) setNarrationActive('planet', false); };
  if (isNativeApp) {
    // ---- Jalur APLIKASI ANDROID (native TTS) ----
    if (isSpeakingNative) {
      await stopSpeaking();
      return;
    }
    try {
      isSpeakingNative = true;
      setNarrationActive('planet', true);
      if (speakBtn) speakBtn.classList.add('speaking');
      await TextToSpeech.speak({
        text: teks,
        lang: 'id-ID',
        rate: 0.95,
        category: 'ambient'
      });
    } catch (err) {
      console.error('Gagal memutar suara (native TTS):', err);
    } finally {
      finishVoice();
      isSpeakingNative = false;
      if (speakBtn) speakBtn.classList.remove('speaking');
    }
  } else {
    // ---- Jalur WEB BROWSER (Web Speech API) ----
    if (!window.speechSynthesis) {
      console.warn('Browser ini tidak mendukung fitur suara (speechSynthesis).');
      return;
    }
    if (window.speechSynthesis.speaking) {
      stopSpeaking();
      return;
    }
    const ucapan = new SpeechSynthesisUtterance(teks);
    ucapan.lang = 'id-ID';
    ucapan.rate = 0.95;
    setNarrationActive('planet', true);
    ucapan.onstart = () => speakBtn && speakBtn.classList.add('speaking');
    ucapan.onend = ucapan.onerror = () => { finishVoice(); if (speakBtn) speakBtn.classList.remove('speaking'); };
    window.speechSynthesis.speak(ucapan);
  }
}

async function stopSpeaking() {
  planetVoiceRequest++;
  setNarrationActive('planet', false);
  const speakBtn = document.getElementById('speak-btn');
  if (isNativeApp) {
    try {
      await TextToSpeech.stop();
    } catch (err) {
      // abaikan jika memang belum ada suara yang jalan
    }
    isSpeakingNative = false;
  } else if (window.speechSynthesis && window.speechSynthesis.speaking) {
    window.speechSynthesis.cancel();
  }
  if (speakBtn) speakBtn.classList.remove('speaking');
}

