(function setupPencarianPlanet() {
  const input = document.getElementById('planet-search');
  const saran = document.getElementById('search-suggestions');
  if (!input || !saran) return;

  const daftarKey = Object.keys(planetNameID);

  function tampilkanSaran(query) {
    const q = query.trim().toLowerCase();
    saran.innerHTML = '';
    if (!q) {
      saran.classList.remove('show');
      return;
    }
    const hasil = daftarKey.filter(k => planetNameID[k].toLowerCase().includes(q));
    if (hasil.length === 0) {
      saran.classList.remove('show');
      return;
    }
    hasil.forEach(key => {
      const item = document.createElement('div');
      item.className = 'search-suggestion-item';
      item.textContent = planetNameID[key];
      item.addEventListener('click', () => {
        goToPlanetByKey(key);
        input.value = '';
        saran.classList.remove('show');
      });
      saran.appendChild(item);
    });
    saran.classList.add('show');
  }

  input.addEventListener('input', () => tampilkanSaran(input.value));
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const q = input.value.trim().toLowerCase();
      const cocok = daftarKey.find(k => planetNameID[k].toLowerCase().startsWith(q));
      if (cocok) {
        goToPlanetByKey(cocok);
        input.value = '';
        saran.classList.remove('show');
      }
    }
  });
  document.addEventListener('click', (e) => {
    if (e.target !== input) saran.classList.remove('show');
  });
})();

