  sun.rotateY(0.001 * settings.acceleration * delta / 16.667);
  mercury.planet.rotateY(0.001 * settings.acceleration * delta / 16.667);
  mercury.planet3d.rotateY(0.004 * settings.accelerationOrbit * delta / 16.667);
  venus.planet.rotateY(0.0005 * settings.acceleration * delta / 16.667)
  venus.Atmosphere.rotateY(0.0005 * settings.acceleration * delta / 16.667);
  venus.planet3d.rotateY(0.0006 * settings.accelerationOrbit * delta / 16.667);
  earth.planet.rotateY(0.005 * settings.acceleration * delta / 16.667);
  earth.Atmosphere.rotateY(0.001 * settings.acceleration * delta / 16.667);
  earth.planet3d.rotateY(0.001 * settings.accelerationOrbit * delta / 16.667);
  mars.planet.rotateY(0.01 * settings.acceleration * delta / 16.667);
  mars.planet3d.rotateY(0.0007 * settings.accelerationOrbit * delta / 16.667);
  jupiter.planet.rotateY(0.005 * settings.acceleration * delta / 16.667);
