import './penguji.js';
import {initReset} from './zepto/reset.js';
import './zepto/style.css';
import {initZepto, showZepto, showTutorial, missionBanner} from './zepto/ui.js';
import {state} from './zepto/state.js';
import {disposeStage} from './zepto/stage.js';
import {stopVoice} from './zepto/voice.js';
import { initSolarSystem } from './script.js';
import { initMisi } from './missions.js';
import { initPlayZone } from './playzone.js';
import { initLab } from './lab.js';
import { initPassport } from './passport.js';
import { initSettings } from './settings.js';
import { initStarfield, pauseStarfield, resumeStarfield } from './starfield.js';
import { ensureMusicStarted, toggleMusic, isMusicOn } from './audio.js';
import { fetchFaktaHarian } from './facts.js';
import { getProgres, tandaiSudahMulai } from './progress.js';

// ======  DAFTAR LAYAR  ======
const screens = {
  pembimbing: document.getElementById("pembimbing-screen"),
  penguji: document.getElementById("penguji-screen"),
  zepto: document.getElementById('zepto-screen'),
  menu: document.getElementById('main-menu'),
  jelajah: document.getElementById('solar-system-screen'),
  misi: document.getElementById('mission-screen'),
  bermain: document.getElementById('playzone-screen'),
  lab: document.getElementById('lab-screen'),
  paspor: document.getElementById('passport-screen'),
  pengaturan: document.getElementById('settings-screen'),
  caraBermain: document.getElementById('howto-screen'),
  tentang: document.getElementById('about-screen')
};

let misiStarted = false;
let bermainStarted = false;
let labStarted = false;

// ======  STARFIELD LATAR BELAKANG GLOBAL  ======
initStarfield(document.getElementById('global-starfield'));

// ======  FAKTA HARIAN & SAPAAN AWAL  ======
document.getElementById('fact-text').textContent = fetchFaktaHarian();
if (getProgres().sudahMulai) {
  document.getElementById('btn-lanjutkan').style.display = 'inline-flex';
  document.getElementById('mascot-sapaan').textContent = 'Senang bertemu lagi, Penjelajah Cilik! Mau lanjut ke mana hari ini?';
}

// ======  FUNGSI NAVIGASI  ======

// ZEPTO: Android and on-screen back share the same route history.
const zeptoRouteHistory=[];
let zeptoReplaying=false;
window.zeptoRemember=function(page,arg){
 if(zeptoReplaying)return;
 const route={page,arg};
 const last=zeptoRouteHistory[zeptoRouteHistory.length-1];
 if(page==='menu'){zeptoRouteHistory.length=0;zeptoRouteHistory.push(route);return;}
 if(!last||last.page!==page||last.arg!==arg)zeptoRouteHistory.push(route);
};
window.zeptoBack=function(){
 const dialog=document.querySelector('dialog[open]');
 if(dialog){const close=dialog.querySelector('#z-understand');if(close)close.click();else dialog.close();return;}
 const screen=document.querySelector('.screen.active-screen');
 if(!screen||screen.id==='main-menu')return;
 const inner=screen.querySelector('#z-list, #z-sims-back, #z-results-back, #z-guess-back, #pz-kembali-kuis, #pz-kembali-cocok, #pz-kembali-susun');
 if(inner){inner.click();return;}
 if(zeptoRouteHistory.length>1)zeptoRouteHistory.pop();
 const previous=zeptoRouteHistory[zeptoRouteHistory.length-1]||{page:'menu'};
 zeptoReplaying=true;
 try{tampilkanLayar(previous.page,previous.arg);}finally{zeptoReplaying=false;}
};

function tampilkanLayar(namaLayar, arg) {
  disposeStage(); stopVoice();
  window.dispatchEvent(new CustomEvent('zepto-leave-solar'));
  window.dispatchEvent(new Event('zepto-navigation'));
  const accessible=['pembimbing','penguji','menu','caraBermain','tentang','pengaturan','petunjuk','evaluasi','progres','paspor'];
  if(!state().pretest&&!accessible.includes(namaLayar))namaLayar='petunjuk';
  window.zeptoRemember(namaLayar,arg);
  const pages={belajar:'belajar',evaluasi:'evaluasi',progres:'progres',misi:'misi',lab:'simulasi',tebak:'tebak',petunjuk:'petunjuk'};
  const page=pages[namaLayar];
  if(namaLayar==='misiLama')namaLayar='misi';
  if(namaLayar==='labLama')namaLayar='lab';
  if(page)namaLayar='zepto';
  Object.values(screens).forEach(screen => screen.classList.remove('active-screen'));
  screens[namaLayar].classList.add('active-screen');
  if(page)showZepto(page,arg);

  if (namaLayar === 'jelajah') {
    pauseStarfield();
    const container = document.getElementById('solar-canvas-container');
    initSolarSystem(container);
    missionBanner(); showTutorial();
    musicBtn.classList.add('hidden-on-solar');
  } else {
    resumeStarfield();
    musicBtn.classList.remove('hidden-on-solar');
  }

  if (namaLayar === 'misi' && !misiStarted) {
    misiStarted = true;
    initMisi(document.getElementById('mission-container'));
  }
  if (namaLayar === 'misi' && misiStarted) {
    // render ulang tiap dibuka supaya status "selesai" selalu terbaru
    initMisi(document.getElementById('mission-container'));
  }

  if (namaLayar === 'bermain') {
    initPlayZone(document.getElementById('playzone-container'), () => tampilkanLayar('menu'));
  }

  if (namaLayar === 'lab') {
    initLab(document.getElementById('lab-container'));
  }

  if (namaLayar === 'paspor') {
    initPassport(document.getElementById('passport-container'));
  }

  if (namaLayar === 'pengaturan') {
    initSettings(document.getElementById('settings-container'));
  }
}

// ======  SPLASH SCREEN  ======
function sembunyikanSplash() {
  const splash=document.getElementById('splash-screen');
  if(splash){splash.classList.add('splash-hidden');setTimeout(()=>splash.remove(),650);}
}
setTimeout(sembunyikanSplash, 900);

// ======  MUSIK AMBIENT  ======
const musicBtn = document.getElementById('music-toggle');
function perbaruiIkonMusik() {
  musicBtn.textContent = isMusicOn() ? '🎵' : '🔇';
  musicBtn.classList.toggle('muted', !isMusicOn());
}
perbaruiIkonMusik();
window.addEventListener('zepto-audio-change', perbaruiIkonMusik);
musicBtn.addEventListener('click', () => { toggleMusic(); perbaruiIkonMusik(); });

function mulaiMusikSekaliSaja() {
  ensureMusicStarted();
  perbaruiIkonMusik();
  document.removeEventListener('click', mulaiMusikSekaliSaja);
}
document.addEventListener('click', mulaiMusikSekaliSaja);

// ======  TOMBOL HALAMAN UTAMA  ======
document.getElementById('btn-mulai').addEventListener('click', () => {
  tandaiSudahMulai();
  tampilkanLayar(state().pretest?'belajar':'petunjuk');
});
document.getElementById('btn-lanjutkan').addEventListener('click', () => tampilkanLayar('paspor'));
document.getElementById('btn-jelajah').addEventListener('click', () => tampilkanLayar('jelajah'));
document.getElementById('btn-misi').addEventListener('click', () => tampilkanLayar('misi'));
document.getElementById('btn-bermain').addEventListener('click', () => tampilkanLayar('bermain'));
document.getElementById('btn-lab').addEventListener('click', () => tampilkanLayar('lab'));
document.getElementById('btn-paspor').addEventListener('click', () => tampilkanLayar('paspor'));
document.getElementById('btn-pengaturan').addEventListener('click', () => tampilkanLayar('pengaturan'));
document.getElementById('btn-cara-bermain').addEventListener('click', () => tampilkanLayar('caraBermain'));
document.getElementById('btn-pembimbing').onclick=()=>tampilkanLayar('pembimbing');
document.getElementById('btn-penguji').onclick=()=>tampilkanLayar('penguji');
document.getElementById('btn-tentang').addEventListener('click', () => tampilkanLayar('tentang'));

// ======  TOMBOL KEMBALI (semua layar)  ======
document.querySelectorAll('[data-back]').forEach(btn => {
  btn.addEventListener('click', () => {
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    window.zeptoBack();
  });
});

initZepto(tampilkanLayar);
initReset({stopAudio:stopVoice});
document.getElementById('btn-belajar').onclick=()=>tampilkanLayar('belajar');
document.getElementById('btn-evaluasi').onclick=()=>tampilkanLayar('evaluasi');
document.getElementById('btn-progres').onclick=()=>tampilkanLayar('progres');
document.getElementById('z-help').onclick=()=>showTutorial(true);
document.getElementById('z-earth-moon').onclick=()=>tampilkanLayar('lab','earth-moon');
window.addEventListener('zepto-navigate',e=>tampilkanLayar(e.detail));
// Tampilkan menu utama saat pertama kali dibuka
tampilkanLayar('menu');
