import {mark} from './zepto/state.js';
import { mainkanSfx } from './audio.js';

// Urutan benar dari Matahari
const urutanBenar = ['☿️ Merkurius', '♀️ Venus', '🌍 Bumi', '🔴 Mars', '🟠 Yupiter', '💍 Saturnus', '🔵 Uranus', '🔷 Neptunus'];

export function initOrdering(container) {
  let kartuTerpilih = null; // untuk mode sentuh-dua-kartu
  let posisi = acak(urutanBenar);

  render();

  function acak(arr) {
    let a = [...arr];
    do {
      for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
      }
    } while (a.every((v, i) => v === arr[i])); // pastikan tidak kebetulan sudah urut
    return a;
  }

  function render() {
    container.innerHTML = `
      <div class="hub-header">
        <h1>🔢 Susun Planet</h1>
        <p class="hub-sub">Urutkan planet dari yang PALING DEKAT Matahari. Seret kartu, atau sentuh dua kartu untuk bertukar posisi.</p>
      </div>
      <div class="order-list" id="order-list"></div>
      <button class="quiz-next-btn" id="order-cek">✅ Periksa Urutan</button>
      <p class="order-feedback" id="order-feedback"></p>
    `;

    const list = container.querySelector('#order-list');
    posisi.forEach((nama, index) => {
      const el = document.createElement('div');
      el.className = 'order-card';
      el.draggable = true;
      el.tabIndex=0;el.setAttribute('role','button');el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}};
      el.dataset.index = index;
      el.innerHTML = `<span class="order-number">${index + 1}</span><span class="order-label">${nama}</span>`;

      // ---- Mode sentuh: tap dua kartu untuk bertukar ----
      el.addEventListener('click', () => pilihUntukTukar(el));

      // ---- Mode drag & drop (mouse di desktop) ----
      el.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', index);
        el.classList.add('order-dragging');
      });
      el.addEventListener('dragend', () => el.classList.remove('order-dragging'));
      el.addEventListener('dragover', (e) => e.preventDefault());
      el.addEventListener('drop', (e) => {
        e.preventDefault();
        const dariIndex = Number(e.dataTransfer.getData('text/plain'));
        const keIndex = Number(el.dataset.index);
        tukarPosisi(dariIndex, keIndex);
      });

      list.appendChild(el);
    });

    container.querySelector('#order-cek').addEventListener('click', periksaUrutan);
  }

  function pilihUntukTukar(el) {
    if (!kartuTerpilih) {
      kartuTerpilih = el;
      el.classList.add('order-selected');
      return;
    }
    if (kartuTerpilih === el) {
      el.classList.remove('order-selected');
      kartuTerpilih = null;
      return;
    }
    const dariIndex = Number(kartuTerpilih.dataset.index);
    const keIndex = Number(el.dataset.index);
    kartuTerpilih.classList.remove('order-selected');
    kartuTerpilih = null;
    tukarPosisi(dariIndex, keIndex);
  }

  function tukarPosisi(dariIndex, keIndex) {
    if (dariIndex === keIndex || isNaN(dariIndex) || isNaN(keIndex)) return;
    [posisi[dariIndex], posisi[keIndex]] = [posisi[keIndex], posisi[dariIndex]];
    mainkanSfx('klik');
    render();
  }

  function periksaUrutan() {
    const feedback = container.querySelector('#order-feedback');
    const benar = posisi.every((v, i) => v === urutanBenar[i]);
    if (benar) {
      mark('games','ordering',10);
      mainkanSfx('benar');
      feedback.innerHTML = '🎉 <strong>Sempurna!</strong> Urutan planetmu sudah benar!';
      feedback.className = 'order-feedback order-feedback-benar';
    } else {
      mainkanSfx('salah');
      feedback.innerHTML = 'Belum tepat, coba lihat lagi urutannya ya. Kamu pasti bisa! 💪';
      feedback.className = 'order-feedback order-feedback-salah';
    }
  }
}
