import * as T from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {objects,planets} from './data.js';
import {getPengaturan} from '../progress.js';
const urls=import.meta.glob('../images/*.jpg',{eager:true,query:'?url',import:'default'});
let teardown=()=>{};
export function disposeStage(){teardown();teardown=()=>{}}
export function mountStage(host,mode,options={}){
 disposeStage();
 const scene=new T.Scene();scene.background=new T.Color('#07152d');
 const camera=new T.PerspectiveCamera(42,1,.1,500);camera.position.set(0,8,22);
 let renderer;
 try{renderer=new T.WebGLRenderer({antialias:true,alpha:false})}catch{host.innerHTML='<p class="z-note">Perangkat ini belum dapat membuka 3D. Materi dan evaluasi tetap bisa dipakai.</p>';return {}}
 renderer.setPixelRatio(Math.min(devicePixelRatio,getPengaturan().grafis==='hemat'?1:1.5));
 renderer.outputColorSpace=T.SRGBColorSpace;host.append(renderer.domElement);
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=3;controls.maxDistance=70;
 scene.add(new T.AmbientLight(0xffffff,.25));
 const light=new T.PointLight(0xffffff,180,100,1);light.position.set(-8,1,0);scene.add(light);
 const fill=new T.DirectionalLight(0xffffff,1.8);fill.position.set(0,6,10);scene.add(fill);
 const loader=new T.TextureLoader();const resources=[];const labels=[];
 function label(text,obj){const e=document.createElement('span');e.className='z-object-label';e.textContent=text;host.append(e);labels.push({e,obj})}
 function body(id,r=1){const d=objects.find(x=>x.id===id);const mat=new T.MeshStandardMaterial({color:0xffffff,roughness:1});
  if(d?.texture){const tex=loader.load(urls['../images/'+d.texture]);tex.colorSpace=T.SRGBColorSpace;mat.map=tex;resources.push(tex)}
  if(id==='Sun'){mat.emissive=new T.Color('#fff0a0');mat.emissiveMap=mat.map;mat.emissiveIntensity=2}
  const mesh=new T.Mesh(new T.SphereGeometry(r,40,24),mat);mesh.userData.id=id;scene.add(mesh);
  if(id==='Saturn'){const ring=new T.Mesh(new T.RingGeometry(r*1.3,r*2,64),new T.MeshStandardMaterial({color:0xd6bd90,side:T.DoubleSide,transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2.5;mesh.add(ring)}
  if(options.labels!==false && !(mode==='rotation'&&id==='Earth'))label(d?.name||id,mesh);return mesh;
 }
 function orbit(r,center=new T.Vector3()){const pts=Array.from({length:100},(_,i)=>new T.Vector3(Math.cos(i/100*Math.PI*2)*r,0,Math.sin(i/100*Math.PI*2)*r).add(center));const line=new T.LineLoop(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0x609ec1}));scene.add(line);return line}
 let update=()=>{};let elapsed=0;let playing=!getPengaturan().kurangiAnimasi;let speed=1;
 if(mode==='rotation'){
  const earth=body('Earth',2.8);body('Sun',.8).position.set(-8,0,0);fill.intensity=0;light.intensity=90;
  const day=new T.Object3D();day.position.set(-4.3,0,0);scene.add(day);label('☀ Siang',day);const night=new T.Object3D();night.position.set(4.3,0,0);scene.add(night);label('☾ Malam',night);
  scene.add(new T.ArrowHelper(new T.Vector3(0,0,-1),new T.Vector3(3.4,0,0),2,0x72ead1));
  const pin=new T.Mesh(new T.SphereGeometry(.12),new T.MeshBasicMaterial({color:0xffd369}));pin.position.set(2.8,0,0);earth.add(pin);update=t=>earth.rotation.y=t*.4;
 }else if(mode==='revolution'||mode==='earth-moon'){
  const isMoon=mode==='earth-moon';const center=body(isMoon?'Earth':'Sun',2);const moving=body(isMoon?'Moon':'Earth',isMoon?.6:1);orbit(6);
  scene.add(new T.ArrowHelper(new T.Vector3(0,0,1),new T.Vector3(6,0,0),2,0x72ead1));
  update=t=>{const a=t*.25;moving.position.set(Math.cos(a)*6,0,Math.sin(a)*6);center.rotation.y=t*.12;moving.rotation.y=t*.3};
 }else if(mode==='solar-eclipse'||mode==='lunar-eclipse'){
  const solar=mode==='solar-eclipse';body('Sun',2).position.set(-8,0,0);const earth=body('Earth',1.5);earth.position.set(solar?4:0,0,0);const moon=body('Moon',.65);
  const shadow=new T.Mesh(new T.CylinderGeometry(solar?.12:.85,solar?.65:1.5,solar?4:5,40,1,true),new T.MeshBasicMaterial({color:0x020716,transparent:true,opacity:.65,side:T.DoubleSide,depthWrite:false}));shadow.rotation.z=Math.PI/2;scene.add(shadow);
  const spot=new T.Mesh(new T.CircleGeometry(solar?.35:.64,40),new T.MeshBasicMaterial({color:0x080914,transparent:true,opacity:.82,side:T.DoubleSide}));spot.rotation.y=-Math.PI/2;scene.add(spot);
  fill.intensity=.7;
  update=t=>{const y=Math.sin(t*.35)*2.5;moon.position.set(solar?0:5,y,0);shadow.position.set(solar?2:2.5,solar?y:0,0);spot.position.set(solar?2.5:4.34,solar?0:y,0);const aligned=Math.abs(y)<.65;shadow.visible=aligned;spot.visible=aligned;options.onStatus?.(aligned?'Ketiga benda segaris: bayangan mengenai '+(solar?'Bumi.':'Bulan.'):'Amati Bulan bergerak menuju garis Matahari dan Bumi.')};
 }else if(mode==='Meteor'){
  const earth=body('Earth',2);earth.position.x=4;
  const atmosphere=new T.Mesh(new T.SphereGeometry(2.35,32,20),new T.MeshBasicMaterial({color:0x66b8ff,transparent:true,opacity:.18}));atmosphere.position.copy(earth.position);scene.add(atmosphere);
  const rock=new T.Mesh(new T.DodecahedronGeometry(.2),new T.MeshStandardMaterial({color:0xaba49b}));scene.add(rock);label('Meteoroid → Meteor',rock);
  const tail=new T.Mesh(new T.ConeGeometry(.18,1.8,12),new T.MeshBasicMaterial({color:0xffcb62,transparent:true,opacity:.8}));tail.rotation.z=Math.PI/2;scene.add(tail);
  update=t=>{const u=(t%8)/8;rock.position.set(-6+u*9,2-u*1.5,0);tail.position.copy(rock.position).add(new T.Vector3(-.8,0,0));tail.visible=rock.position.distanceTo(earth.position)<2.4;rock.visible=u<.99;options.onStatus?.(tail.visible?'Meteor: cahaya saat memasuki atmosfer.':'Meteoroid: batuan kecil di luar angkasa.')};
 }else if(mode==='compare'){
  const a=planets.find(x=>x.id===options.a)||planets[2];const b=planets.find(x=>x.id===options.b)||planets[4];const max=Math.max(a.size,b.size);const x=body(a.id,3*a.size/max);const y=body(b.id,3*b.size/max);x.position.x=-4;y.position.x=4;update=t=>{x.rotation.y=y.rotation.y=t*.2};
 }else{const target=objects.find(x=>x.id===mode)||planets[2];const mesh=body(target.id,2.5);update=t=>mesh.rotation.y=t*.2}
 const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};const observer=new ResizeObserver(resize);observer.observe(host);resize();
 let raf,last=performance.now(),alive=true;
 function frame(now){if(!alive)return;raf=requestAnimationFrame(frame);const delta=Math.min((now-last)/1000,.05);last=now;if(document.hidden||!host.closest('.active-screen'))return;if(playing)elapsed+=delta*speed;update(elapsed);controls.update();renderer.render(scene,camera);labels.forEach(({e,obj})=>{const p=obj.getWorldPosition(new T.Vector3()).project(camera);e.style.left=(p.x*.5+.5)*host.clientWidth+'px';e.style.top=(-p.y*.5+.5)*host.clientHeight+22+'px';e.hidden=p.z>1})}frame(last);
 teardown=()=>{alive=false;cancelAnimationFrame(raf);observer.disconnect();controls.dispose();scene.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose())});resources.forEach(t=>t.dispose());renderer.dispose();renderer.forceContextLoss();host.replaceChildren()};
 return {play(){playing=true},pause(){playing=false},reset(){elapsed=0;update(0)},speed(v){speed=v}};
}
