import { getProgres, semuaLencanaInfo, daftarPlanetUtama } from './progress.js';

const namaPlanetID = {
  Mercury: 'Merkurius', Venus: 'Venus', Earth: 'Bumi', Mars: 'Mars',
  Jupiter: 'Yupiter', Saturn: 'Saturnus', Uranus: 'Uranus', Neptune: 'Neptunus'
};
const emojiPlanet = {
  Mercury: '☿️', Venus: '♀️', Earth: '🌍', Mars: '🔴',
  Jupiter: '🟠', Saturn: '💍', Uranus: '🔵', Neptune: '🔷'
};

export function initPassport(container) {
  const progres = getProgres();
  const planetKeys = daftarPlanetUtama();
  const semuaLencana = semuaLencanaInfo();

  const stempelHTML = planetKeys.map(key => {
    const sudah = !!progres.stempelPlanet[key];
    return `
      <div class="stamp-slot ${sudah ? 'stamp-filled' : ''}">
        <span class="stamp-slot-icon">${sudah ? emojiPlanet[key] : '❔'}</span>
        <span class="stamp-slot-label">${namaPlanetID[key]}</span>
      </div>
    `;
  }).join('');

  const lencanaHTML = semuaLencana.map(l => {
    const didapat = progres.lencana.includes(l.id);
    return `
      <div class="badge-item ${didapat ? '' : 'badge-locked'}">
        <span class="badge-icon">${didapat ? l.ikon : '🔒'}</span>
        <span class="badge-name">${l.nama}</span>
      </div>
    `;
  }).join('');

  const riwayatHTML = progres.riwayatKuis.length
    ? progres.riwayatKuis.slice(0, 8).map(r => {
        const tgl = new Date(r.tanggal);
        const tglStr = tgl.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
        return `<div class="history-row"><span>${tglStr}</span><span>${r.skor} / ${r.total}</span></div>`;
      }).join('')
    : `<p class="hub-sub">Belum ada riwayat kuis. Yuk coba Zona Bermain!</p>`;

  container.innerHTML = `
    <div class="hub-header">
      <h1>🪪 Paspor Astronaut</h1>
      <p class="hub-sub">Progres petualanganmu di tata surya</p>
    </div>

    <div class="passport-card">
      <h2 class="passport-section-title">🌟 Stempel Planet (${Object.keys(progres.stempelPlanet).length}/${planetKeys.length})</h2>
      <div class="stamp-grid">${stempelHTML}</div>
    </div>

    <div class="passport-card">
      <h2 class="passport-section-title">🎖️ Lencana Pencapaian</h2>
      <div class="badges-row">${lencanaHTML}</div>
    </div>

    <div class="passport-card">
      <h2 class="passport-section-title">📊 Misi Selesai</h2>
      <p class="passport-stat">${Object.keys(progres.misiSelesai).length} misi telah diselesaikan</p>
    </div>

    <div class="passport-card">
      <h2 class="passport-section-title">📝 Riwayat Kuis</h2>
      ${riwayatHTML}
    </div>

    <p class="passport-note">💾 Progres disimpan otomatis di perangkat ini saja (tidak tersimpan online).</p>
  `;
}
