// ======  STARFIELD: bintang berkelap-kelip + meteor jatuh  ======
// Canvas latar belakang global yang dipakai di menu, kuis, profil, dan perbandingan.
// Di layar Tata Surya 3D tidak dipakai karena sudah ada skybox bintang dari Three.js.

let ctx, canvas, stars, meteors, animId, running = false;

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}

function buatBintang(jumlah) {
  const arr = [];
  for (let i = 0; i < jumlah; i++) {
    arr.push({
      x: Math.random() * window.innerWidth,
      y: Math.random() * window.innerHeight,
      r: Math.random() * 1.4 + 0.3,
      fase: Math.random() * Math.PI * 2,
      kecepatanKedip: 0.005 + Math.random() * 0.02
    });
  }
  return arr;
}

function mungkinBuatMeteor() {
  // Peluang kecil tiap frame untuk memunculkan meteor baru
  if (Math.random() < 0.004 && meteors.length < 3) {
    const startX = Math.random() * window.innerWidth;
    meteors.push({
      x: startX,
      y: -20,
      panjang: 80 + Math.random() * 60,
      kecepatan: 8 + Math.random() * 6,
      sudut: Math.PI / 4 + (Math.random() * 0.2 - 0.1),
      alpha: 1
    });
  }
}

function gambar() {
  if (!running) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Bintang berkelap-kelip
  for (const s of stars) {
    s.fase += s.kecepatanKedip;
    const opacity = 0.4 + Math.abs(Math.sin(s.fase)) * 0.6;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,255,255,${opacity.toFixed(2)})`;
    ctx.fill();
  }

  // Meteor jatuh
  mungkinBuatMeteor();
  for (let i = meteors.length - 1; i >= 0; i--) {
    const m = meteors[i];
    const dx = Math.cos(m.sudut) * m.panjang;
    const dy = Math.sin(m.sudut) * m.panjang;

    const gradient = ctx.createLinearGradient(m.x, m.y, m.x - dx, m.y - dy);
    gradient.addColorStop(0, `rgba(255,255,255,${m.alpha})`);
    gradient.addColorStop(1, 'rgba(255,255,255,0)');

    ctx.strokeStyle = gradient;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(m.x, m.y);
    ctx.lineTo(m.x - dx, m.y - dy);
    ctx.stroke();

    m.x += Math.cos(m.sudut) * m.kecepatan;
    m.y += Math.sin(m.sudut) * m.kecepatan;

    if (m.y > window.innerHeight + 50 || m.x < -50) {
      meteors.splice(i, 1);
    }
  }

  animId = requestAnimationFrame(gambar);
}

/**
 * Membuat & menjalankan starfield pada sebuah <canvas>.
 * @param {HTMLCanvasElement} canvasEl
 */
export function initStarfield(canvasEl) {
  canvas = canvasEl;
  ctx = canvas.getContext('2d');
  stars = buatBintang(160);
  meteors = [];
  resize();
  window.addEventListener('resize', resize);
  running = true;
  gambar();
}

export function pauseStarfield() {
  running = false;
  if (animId) cancelAnimationFrame(animId);
}

export function resumeStarfield() {
  if (!running && ctx) {
    running = true;
    gambar();
  }
}
