const area=document.querySelector('#penguji-screen');
const get=id=>area.querySelector('#'+id);
const key='zepto_penguji_v1';
let daftar=[],changed=false;
const fields=['nama','peran','institusi','bio'];
function valid(rows){
 if(!Array.isArray(rows))throw Error();
 return rows.filter(r=>r&&typeof r.nama==='string'&&r.nama.trim()).map(r=>Object.fromEntries(fields.map(k=>[k,typeof r[k]==='string'?r[k]:''])));
}
function render(){
 const list=get('pj-list');list.replaceChildren();
 if(!daftar.length){list.textContent='Belum ada profil dosen penguji.';return}
 daftar.forEach((r,i)=>{
 const card=document.createElement('article');card.className='pj-card';
 for(const [tag,value] of [['small',r.peran||'Dosen penguji'],['h3',r.nama],['p',r.institusi],['p',r.bio]]){
 if(value){const el=document.createElement(tag);el.textContent=value;card.append(el)}}
 for(const [label,fn] of [['Edit',()=>form(i)],['Hapus',()=>{if(confirm('Hapus profil '+r.nama+' dari perangkat ini?')){if(save(daftar.filter((_,j)=>j!==i)))closeForm()}}]]){
 const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=fn;card.append(b)}
 list.append(card)});
}
function save(rows){try{localStorage.setItem(key,JSON.stringify(rows));daftar=rows;changed=true;render();get('pj-status').textContent='Perubahan tersimpan di perangkat ini.';return true}catch{get('pj-status').textContent='Gagal menyimpan. Periksa izin penyimpanan perangkat.';return false}}
let index=-1;
function form(i){index=i;get('pj-form').hidden=false;get('pj-title').textContent=i<0?'Tambah profil':'Edit profil';for(const k of fields)get('pj-'+k).value=daftar[i]?.[k]||'';get('pj-nama').focus()}
function closeForm(){index=-1;get('pj-form').hidden=true;get('pj-form').reset()}
get('pj-add').onclick=()=>form(-1);get('pj-cancel').onclick=closeForm;
get('pj-form').onsubmit=e=>{e.preventDefault();const r=Object.fromEntries(fields.map(k=>[k,get('pj-'+k).value.trim()]));if(!r.nama){get('pj-status').textContent='Isi nama dosen terlebih dahulu.';get('pj-nama').focus();return}const rows=daftar.slice();if(index<0)rows.push(r);else rows[index]=r;if(save(rows))closeForm()};
get('pj-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(daftar,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='penguji.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)};
async function init(){try{const data=localStorage.getItem(key);if(data!==null){daftar=valid(JSON.parse(data));render();return}}catch{}
 try{const res=await fetch('./penguji.json',{cache:'no-store'});if(!res.ok)throw Error();const rows=valid(await res.json());if(!changed)daftar=rows}catch{get('pj-status').textContent='Daftar awal tidak dapat dimuat.'}render()}
if(window.Capacitor?.isNativePlatform?.())get('pj-export').hidden=true;
init();
