/**
 * Ambil satu fakta yang konsisten sepanjang hari yang sama (berubah tiap hari).
 */
export function fetchFaktaHarian() {
  const sekarang = new Date();
  const dayOfYear = Math.floor(
    (sekarang - new Date(sekarang.getFullYear(), 0, 0)) / 86400000
  );
  const index = dayOfYear % daftarFakta.length;
  return daftarFakta[index];
}

