import { initQuiz } from './quiz.js';
import { initMatching } from './matching.js';
import { initOrdering } from './ordering.js';

export function initPlayZone(container, kembaliKeMenu) {
  render();

  function render() {
    container.innerHTML = `
      <div class="hub-header">
        <h1>🎮 Zona Bermain</h1>
        <p class="hub-sub">Pilih permainan yang ingin kamu mainkan</p>
      </div>
      <div class="playzone-grid"><button class="playzone-card" id="pz-tebak"><span class="playzone-icon">🪐</span><span class="playzone-title">Tebak Planet 3D</span><span class="playzone-desc">Kenali planet dari modelnya</span></button><button class="playzone-card" id="pz-cari"><span class="playzone-icon">🔍</span><span class="playzone-title">Cari Planet</span><span class="playzone-desc">Temukan objek dalam misi 3D</span></button>
        <button class="playzone-card" id="pz-kuis">
          <span class="playzone-icon">📝</span>
          <span class="playzone-title">Kuis Tata Surya</span>
          <span class="playzone-desc">Uji pengetahuanmu dengan soal pilihan ganda</span>
        </button>
        <button class="playzone-card" id="pz-cocok">
          <span class="playzone-icon">🧩</span>
          <span class="playzone-title">Cocokkan Planet</span>
          <span class="playzone-desc">Pasangkan planet dengan nama atau cirinya</span>
        </button>
        <button class="playzone-card" id="pz-susun">
          <span class="playzone-icon">🔢</span>
          <span class="playzone-title">Susun Planet</span>
          <span class="playzone-desc">Urutkan planet dari yang terdekat Matahari</span>
        </button>
      </div>
    `;

    container.querySelector('#pz-tebak').onclick=()=>window.dispatchEvent(new CustomEvent('zepto-navigate',{detail:'tebak'}));
    container.querySelector('#pz-cari').onclick=()=>window.dispatchEvent(new CustomEvent('zepto-navigate',{detail:'misi'}));
    container.querySelector('#pz-kuis').addEventListener('click', () => {
      container.innerHTML = `<button class="mission-back" id="pz-kembali-kuis">⬅ Zona Bermain</button><div id="pz-kuis-area"></div>`;
      container.querySelector('#pz-kembali-kuis').addEventListener('click', render);
      initQuiz(container.querySelector('#pz-kuis-area'), render);
    });

    container.querySelector('#pz-cocok').addEventListener('click', () => {
      container.innerHTML = `<button class="mission-back" id="pz-kembali-cocok">⬅ Zona Bermain</button><div id="pz-cocok-area"></div>`;
      container.querySelector('#pz-kembali-cocok').addEventListener('click', render);
      initMatching(container.querySelector('#pz-cocok-area'));
    });

    container.querySelector('#pz-susun').addEventListener('click', () => {
      container.innerHTML = `<button class="mission-back" id="pz-kembali-susun">⬅ Zona Bermain</button><div id="pz-susun-area"></div>`;
      container.querySelector('#pz-kembali-susun').addEventListener('click', render);
      initOrdering(container.querySelector('#pz-susun-area'));
    });
  }
}
