import {lessons,objects,planets,missions,questions,missionById} from './data.js';
import {state,save,mark,reward,escapeHTML as esc,scoreAnswers,canPost} from './state.js';
import {speak,stopVoice} from './voice.js';
import {mountStage,disposeStage} from './stage.js';
import {getProgres} from '../progress.js';
let nav,root;
const $=s=>root.querySelector(s);
const on=(s,fn)=>$(s)?.addEventListener('click',fn);
const btn=(id,text)=>`<button class="z-btn" id="${id}">${text}</button>`;
function head(title,sub=''){return `<div class="z-heading"><p class="z-eyebrow">ZEPTO · KELAS VI</p><h1>${title}</h1><p>${sub}</p></div>`}
function card(id,icon,title,sub){return `<button class="z-card" data-id="${id}"><span class="z-icon">${icon}</span><strong>${title}</strong><span>${sub}</span><b>Jelajahi →</b></button>`}
export function initZepto(navigate){nav=navigate;root=document.querySelector('#zepto-content');
 window.addEventListener('zepto-toast',e=>{const t=document.querySelector('#zepto-toast');t.textContent=e.detail;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3200)});
 window.addEventListener('zepto-progress',refreshHeader);refreshHeader();
 window.addEventListener('zepto-selected',e=>{const {key,source}=e.detail;mark('explored',key,3);const s=state();const m=missionById(s.activeMission);if(!m||source!=='direct')return;if(m.targets.includes(key)){if(!s.found.includes(key))s.found.push(key);if(m.targets.every(x=>s.found.includes(x))){s.missions=[...new Set([...s.missions,m.id])];s.activeMission=null;s.found=[];reward('mission:'+m.id,10,s);if(m.id==='home')mark('games','find',10);window.dispatchEvent(new CustomEvent('zepto-toast',{detail:'✨ MISI BERHASIL! +10 Bintang ZEPTO ⭐'}))}else save(s)}else window.dispatchEvent(new CustomEvent('zepto-toast',{detail:'Belum tepat. '+m.text}));missionBanner()});
 document.querySelector('#z-cancel-mission').onclick=()=>{const s=state();s.activeMission=null;s.found=[];save(s);missionBanner()};
}
function refreshHeader(){const s=state();document.querySelector('#z-stars').textContent=`⭐ ${s.stars} Bintang ZEPTO`;document.querySelector('#z-level').textContent=s.level}
export function missionBanner(){const m=missionById(state().activeMission);const banner=document.querySelector('#z-mission-banner');banner.hidden=!m;if(m)document.querySelector('#z-mission-text').textContent=m.text+' Ketuk objek 3D-nya.'}
export function showZepto(page,arg){disposeStage();stopVoice();root.innerHTML='';({belajar:learn,evaluasi:evaluate,progres:progress,misi:missionPage,simulasi:simulations,tebak:guess,petunjuk:intro}[page]||learn)(arg)}
export function intro(){root.innerHTML=head('Mulai petualanganmu 🚀','Ikuti langkah singkat sebelum menjelajah.')+`<div class="z-panel"><h2>Petunjuk</h2><p>👆 Ketuk menu dan objek untuk belajar. 🔊 Dengarkan penjelasan jika kamu ingin dibacakan.</p><h2>Tujuan pembelajaran</h2><ul><li>Menyebutkan delapan planet dan urutannya.</li><li>Mengenali ciri Matahari, planet, dan Bulan.</li><li>Membedakan rotasi, revolusi, dan dua jenis gerhana.</li></ul><p>Isi nama dan kelas, lalu kerjakan pretest. Setelah itu, semua menu belajar dapat dijelajahi.</p>${btn('z-start-pre','Lanjut ke pretest →')}</div>`;on('#z-start-pre',()=>evaluate())}
function learn(id){if(id){const l=lessons.find(x=>x.id===id);root.innerHTML=head(l.icon+' '+l.name,'Materi ZEPTO')+`<article class="z-panel z-lesson"><p class="z-large">${l.text}</p><div class="z-actions">${btn('z-list','← Daftar materi')}${btn('z-read','🔊 Dengarkan')}${btn('z-done',state().read.includes(id)?'✅ Sudah dipelajari':'⭐ Sudah dipelajari · +2')}${btn('z-see','🪐 Lihat 3D')}</div></article>`;on('#z-list',()=>learn());on('#z-read',()=>speak(l.name+'. '+l.text));on('#z-done',()=>{mark('read',id,2);$('#z-done').textContent='✅ Sudah dipelajari'});on('#z-see',()=>{if(['rotation','revolution','solar-eclipse','lunar-eclipse'].includes(id))simulations(id);else if(id==='Meteor')simulations('Meteor');else{nav('jelajah');if(id!=='solar')window.dispatchEvent(new CustomEvent('zepto-focus',{detail:id}))}});return}
 root.innerHTML=head('📚 Belajar bersama ZEPTO','Baca, dengarkan, lalu amati dalam 3D.')+`<h2>Materi inti · ${state().read.filter(x=>lessons.slice(0,15).some(l=>l.id===x)).length}/15</h2><div class="z-grid">${lessons.slice(0,15).map(l=>card(l.id,l.icon,l.name,state().read.includes(l.id)?'✅ Sudah dipelajari':'Pelajaran singkat · +2 ⭐')).join('')}</div><h2 class="z-space">Tahukah kamu?</h2><div class="z-grid">${lessons.slice(15).map(l=>card(l.id,l.icon,l.name,'Pengetahuan tambahan')).join('')}</div>`;root.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>learn(b.dataset.id));
}
function evaluate(){const s=state();if(s.attempt){exam();return}if(!s.profile){root.innerHTML=head('📝 Kenalan dulu, yuk!','Nama dan kelas digunakan untuk mencatat hasil belajarmu.')+`<form id="z-profile" class="z-panel"><label>Nama siswa<input name="name" maxlength="60" required autocomplete="name" placeholder="Tulis namamu"></label><label>Kelas<input name="className" maxlength="20" value="VI" required></label><p class="z-note">Progres disimpan di browser perangkat ini. Gunakan perangkat dan browser yang sama untuk melanjutkan.</p><button class="z-btn z-primary" type="submit">Simpan dan lanjutkan</button></form>`;$('#z-profile').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),className=String(f.get('className')).trim();if(!name||!className)return;const p=state();p.profile={name,className};if(save(p))evaluate()};return}
 if(!s.pretest){root.innerHTML=head('Pretest ZEPTO','Apa yang sudah kamu ketahui tentang Tata Surya?')+`<div class="z-panel"><p>Halo, <strong>${esc(s.profile.name)}</strong>! Kerjakan 10 soal. Tidak ada batas waktu. Jawaban benar tidak ditampilkan selama tes.</p>${btn('z-pre','Mulai pretest →')}</div>`;on('#z-pre',()=>startExam('pre'));return}
 root.innerHTML=head('📝 Evaluasi ZEPTO','Lihat perkembangan pengetahuanmu.')+`<div class="z-panel"><h2>${esc(s.profile.name)} · Kelas ${esc(s.profile.className)}</h2><div class="z-stats"><div>Pretest<strong>${s.pretest.score}</strong></div><div>Posttest<strong>${s.posttest?.score??'—'}</strong></div><div>Peningkatan<strong>${s.posttest?`${s.posttest.score-s.pretest.score>=0?'+':''}${s.posttest.score-s.pretest.score}`:'—'}</strong></div></div><p>${s.posttest?(s.posttest.score>s.pretest.score?'Hebat! Pengetahuanmu tentang Tata Surya semakin meningkat! 🚀':'Terima kasih sudah belajar! Terus berlatih memahami materi yang belum dikuasai.'):'Selesaikan setidaknya satu materi dan jelajahi satu objek 3D sebelum posttest.'}</p><div class="z-actions">${!s.posttest?`<button id="z-post" class="z-btn z-primary" ${canPost(s)?'':'disabled'}>Mulai posttest</button>`:btn('z-results','Lihat rincian hasil')}${btn('z-go-learn','📚 Belajar')}${btn('z-practice','🧠 Kuis latihan')}</div></div>`;on('#z-post',()=>startExam('post'));on('#z-go-learn',()=>learn());on('#z-practice',()=>nav('bermain'));on('#z-results',results);
}
function startExam(type){const s=state();if(type==='post'&&!canPost(s))return;s.attempt={type,index:0,answers:[],startedAt:new Date().toISOString()};if(save(s))exam()}
function exam(){const s=state(),a=s.attempt;if(!a)return evaluate();const q=questions[a.index];let choice=a.answers[a.index]?.choice??null;const offset=a.type==='post'?2:0;const options=q.options.map((v,i)=>({text:v,index:i}));if(offset)options.push(...options.splice(0,offset));
 root.innerHTML=head((a.type==='pre'?'Pretest':'Posttest')+' ZEPTO',`Soal ${a.index+1} dari ${questions.length}`)+`<div class="z-panel"><progress value="${a.index}" max="${questions.length}"></progress><h2>${q[a.type]}</h2><div class="z-options">${options.map(o=>`<button class="z-answer ${choice===o.index?'selected':''}" data-choice="${o.index}">${o.text}</button>`).join('')}</div><p class="z-note">Pilih satu jawaban. Kamu dapat mengubah pilihan sebelum melanjutkan.</p><div class="z-actions">${btn('z-question-audio','🔊 Dengarkan soal')}<button class="z-btn z-primary" id="z-next" ${choice===null?'disabled':''}>${a.index===9?'Selesaikan tes':'Soal berikutnya →'}</button></div></div>`;
 root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=Number(b.dataset.choice);root.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));$('#z-next').disabled=false;const current=state();current.attempt.answers[a.index]={id:q.id,choice,correct:q.answer};save(current)});
 on('#z-question-audio',()=>speak(q[a.type]+'. '+options.map(o=>o.text).join('. ')));
 on('#z-next',()=>{const next=state();if(!next.attempt||choice===null)return;next.attempt.index++;if(next.attempt.index===questions.length){const result={...scoreAnswers(next.attempt.answers),answers:next.attempt.answers,profile:{...next.profile},date:new Date().toISOString(),startedAt:next.attempt.startedAt};next[a.type==='pre'?'pretest':'posttest']=result;next.attempt=null;if(save(next)){if(a.type==='post')results();else evaluate()}}else if(save(next))exam()});
}
function results(){const s=state();root.innerHTML=head('Hasil Belajar ZEPTO',esc(s.profile.name)+' · Kelas '+esc(s.profile.className))+`<div class="z-panel"><div class="z-stats"><div>Pretest<strong>${s.pretest.score}</strong></div><div>Posttest<strong>${s.posttest?.score??'—'}</strong></div><div>Peningkatan<strong>${s.posttest?`${s.posttest.score-s.pretest.score>=0?'+':''}${s.posttest.score-s.pretest.score}`:'—'}</strong></div></div><p>${s.posttest?.score>s.pretest.score?'Hebat! Pengetahuanmu tentang Tata Surya semakin meningkat! 🚀':'Yuk, lanjutkan petualangan dan latihanmu.'}</p><div class="z-table-wrap"><table><thead><tr><th>Tes</th><th>Benar</th><th>Salah</th><th>Tanggal</th></tr></thead><tbody>${[['Pretest',s.pretest],['Posttest',s.posttest]].filter(([,r])=>r).map(([name,r])=>`<tr><td>${name}</td><td>${r.correct}</td><td>${r.wrong}</td><td>${new Date(r.date).toLocaleString('id-ID')}</td></tr>`).join('')}</tbody></table></div><div class="z-actions">${btn('z-print','🖨 Cetak hasil')}${btn('z-results-back','← Evaluasi')}</div></div>`;on('#z-print',()=>window.print());on('#z-results-back',evaluate)}
function progress(){const s=state(),old=getProgres();const best=Math.max(0,...old.riwayatKuis.map(q=>Math.round(q.skor/q.total*100)));const stats=[['Materi inti',s.read.filter(id=>lessons.slice(0,15).some(l=>l.id===id)).length+'/15'],['Planet dijelajahi',planets.filter(p=>s.explored.includes(p.id)).length+'/8'],['Objek tambahan',objects.filter(p=>!planets.includes(p)&&p.id!=='Sun'&&s.explored.includes(p.id)).length+'/5'],['Misi',s.missions.length+'/7'],['Permainan',s.games.length+'/4'],['Kuis terbaik',best],['Pretest',s.pretest?.score??'—'],['Posttest',s.posttest?.score??'—']];root.innerHTML=head('📊 Progres Belajarku',`${esc(s.profile?.name||'Penjelajah')} · ${s.level}`)+`<div class="z-stats z-progress-stats">${stats.map(([k,v])=>`<div>${k}<strong>${v}</strong></div>`).join('')}</div><div class="z-panel"><h2>⭐ ${s.stars} Bintang ZEPTO</h2><progress value="${Math.min(s.stars,250)}" max="250"></progress><p class="z-note">Astronaut Pemula: 0 · Penjelajah Planet: 75 · Kapten ZEPTO: 150 · Master Tata Surya: 250 bintang.</p><p>Materi +2 · Objek +3 · Misi +10 · Permainan +10 · Jawaban kuis benar +5.</p><p class="z-note">Hadiah diberikan sekali per pencapaian atau soal agar adil.</p><h2>Lencana</h2><div class="z-badges">${s.badges.length?s.badges.map(b=>`<span>${b}</span>`).join(''):'Mulai menjelajah untuk mendapatkan lencana pertamamu.'}</div><div class="z-actions">${btn('z-old','🪪 Paspor & riwayat lama')}${btn('z-eval','📝 Hasil belajar')}</div></div>`;on('#z-old',()=>nav('paspor'));on('#z-eval',evaluate)}
function missionPage(){root.innerHTML=head('🚀 Misi ZEPTO','Cari dan ketuk objek yang benar dalam Tata Surya 3D.')+`<div class="z-grid">${missions.map((m,i)=>card(m.id,'0'+(i+1),m.name,(state().missions.includes(m.id)?'✅ Selesai · ':'')+m.text)).join('')}</div><div class="z-actions">${btn('z-old-missions','Buka misi cerita versi awal')}</div>`;root.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{const m=missionById(b.dataset.id),s=state();s.activeMission=m.id;s.found=[];save(s);nav('jelajah');missionBanner();speak(m.text)});on('#z-old-missions',()=>nav('misiLama'))}
const sims=[['earth-moon','🌍','Sistem Bumi dan Bulan','Amati Bulan mengelilingi Bumi.'],['rotation','🌗','Rotasi Bumi','Satu putaran sekitar 24 jam.'],['revolution','☀️','Revolusi Bumi','Satu putaran orbit sekitar 365 hari.'],['solar-eclipse','🌘','Gerhana Matahari','Matahari → Bulan → Bumi.'],['lunar-eclipse','🌒','Gerhana Bulan','Matahari → Bumi → Bulan.'],['compare','📏','Perbandingan Planet 3D','Pilih dua planet dan amati ukurannya.'],['Meteor','🌠','Meteor dan Meteoroid','Batuan angkasa memasuki atmosfer.']];
function simulations(mode){if(mode==='Meteor')mark('explored','Meteor',3);if(!mode){root.innerHTML=head('🌘 Simulasi ZEPTO','Putar kamera, perbesar, dan amati gerakannya.')+`<div class="z-grid">${sims.map(([id,icon,name,text])=>card(id,icon,name,text)).join('')}</div><div class="z-actions">${btn('z-old-lab','🔬 Simulasi dan tabel perbandingan versi awal')}</div>`;root.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>simulations(b.dataset.id));on('#z-old-lab',()=>nav('labLama'));return}
 const def=sims.find(x=>x[0]===mode);root.innerHTML=head(def[1]+' '+def[2],def[3])+`<div class="z-panel">${mode==='compare'?`<div class="z-actions"><label>Planet pertama<select id="z-compare-a">${planets.map(p=>`<option value="${p.id}" ${p.id==='Earth'?'selected':''}>${p.name}</option>`).join('')}</select></label><label>Planet kedua<select id="z-compare-b">${planets.map(p=>`<option value="${p.id}" ${p.id==='Jupiter'?'selected':''}>${p.name}</option>`).join('')}</select></label></div>`:''}<div class="z-stage" id="z-stage"></div><p id="z-sim-status" aria-live="polite">${lessons.find(l=>l.id===mode)?.text||'Geser untuk memutar kamera. Cubit atau scroll untuk memperbesar.'}</p><div class="z-actions">${btn('z-play','▶ Mulai')}${btn('z-pause','⏸ Jeda')}${btn('z-reset','↻ Ulangi')}<label>Kecepatan<select id="z-speed"><option value="0.5">0.5× Lambat</option><option value="1" selected>1× Normal</option><option value="2">2× Cepat</option></select></label>${btn('z-narrate','🔊 Dengarkan')}${btn('z-sims-back','← Simulasi')}</div><p class="z-note">Model pembelajaran: jarak, ukuran, dan waktu disederhanakan.${mode==='compare'?' Perbandingan diameter kedua planet mengikuti rasio yang sama.':''}</p><div id="z-comparison"></div></div>`;
 let stage;const setup=()=>{stage=mountStage($('#z-stage'),mode,{a:$('#z-compare-a')?.value,b:$('#z-compare-b')?.value,onStatus:text=>{if($('#z-sim-status'))$('#z-sim-status').textContent=text}});if(mode==='compare'){const a=planets.find(p=>p.id===$('#z-compare-a').value),b=planets.find(p=>p.id===$('#z-compare-b').value);$('#z-comparison').innerHTML=`<p>${a.size===b.size?'Kedua pilihan berukuran sama.':`${a.size>b.size?a.name:b.name} lebih besar daripada ${a.size>b.size?b.name:a.name}.`}</p><div class="z-table-wrap"><table><thead><tr><th>Ciri</th><th>${a.name}</th><th>${b.name}</th></tr></thead><tbody>${[['Ukuran (Bumi = 1)','size'],['Suhu','temp'],['Rotasi','rotation'],['Revolusi','revolution'],['Satelit','moons']].map(([n,k])=>`<tr><td>${n}</td><td>${a[k]}</td><td>${b[k]}</td></tr>`).join('')}</tbody></table></div>`}};setup();on('#z-play',()=>stage.play?.());on('#z-pause',()=>stage.pause?.());on('#z-reset',()=>stage.reset?.());$('#z-speed').onchange=e=>stage.speed?.(+e.target.value);on('#z-narrate',()=>speak(def[2]+'. '+($('#z-sim-status')?.textContent||def[3])));on('#z-sims-back',()=>{disposeStage();simulations()});['#z-compare-a','#z-compare-b'].forEach(s=>{if($(s))$(s).onchange=setup});
}
function guess(){const deck=[...planets].sort(()=>Math.random()-.5);let i=0,correct=0;function turn(){disposeStage();if(i===deck.length){if(correct===deck.length)mark('games','guess',10);root.innerHTML=head('🎉 Tebak Planet selesai',`${correct} dari ${deck.length} jawaban benar.`)+`<div class="z-panel"><p>${correct===deck.length?'Semua planet berhasil dikenali!':'Coba lagi untuk mengenali semua planet dan mendapatkan 10 bintang.'}</p>${btn('z-guess-retry','Main lagi')}${btn('z-guess-back','← Bermain')}</div>`;on('#z-guess-retry',guess);on('#z-guess-back',()=>nav('bermain'));return}
 const p=deck[i];const choices=[p,...planets.filter(x=>x!==p).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);root.innerHTML=head('🎮 Tebak Planet 3D',`Planet ${i+1} dari 8 · Amati bentuk dan teksturnya.`)+`<div class="z-panel"><div class="z-stage" id="z-stage"></div><h2>Planet apakah ini?</h2><div class="z-options">${choices.map(x=>`<button class="z-answer" data-planet="${x.id}">${x.name}</button>`).join('')}</div><p id="z-guess-feedback" aria-live="polite"></p><button id="z-guess-next" class="z-btn" hidden>Lanjut →</button></div>`;mountStage($('#z-stage'),p.id,{labels:false});root.querySelectorAll('[data-planet]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-planet]').forEach(x=>x.disabled=true);const ok=b.dataset.planet===p.id;if(ok)correct++;$('#z-guess-feedback').textContent=(ok?'Betul! ':'Belum tepat. ')+p.name+'. '+p.text;$('#z-guess-next').hidden=false});on('#z-guess-next',()=>{i++;turn()})}turn()}
export function showTutorial(force=false){if(state().tutorial&&!force)return;const d=document.querySelector('#z-tutorial');d.showModal();document.querySelector('#z-understand').onclick=()=>{const s=state();s.tutorial=true;save(s);d.close()}}
