// ======  PUSAT DATA PROGRES & PENGATURAN  ======
// Semua progres disimpan di localStorage PERANGKAT INI SAJA (tidak online/akun).

const KEY_PROGRES = 'progresAstronaut_v2';
const KEY_PROGRES_LAMA = 'kuisStats'; // dari versi sebelumnya, untuk migrasi
const KEY_FAVORIT_LAMA = 'planetFavorit';

const DAFTAR_PLANET_KEY = ['Mercury','Venus','Earth','Mars','Jupiter','Saturn','Uranus','Neptune'];

function defaultProgres() {
  return {
    stempelPlanet: {},      // { Mercury: true, ... } -> planet yang sudah dikunjungi (dibuka kartunya)
    misiSelesai: {},        // { kenaliBumi: true, ... }
    lencana: [],            // ['pemula', 'rajin', ...]
    riwayatKuis: [],        // [{tanggal, skor, total}]
    sudahMulai: false,      // untuk tombol "Lanjutkan Petualangan"
    pengaturan: {
      musik: true,
      efekSuara: true,
      narasi: true,
      grafis: 'tinggi',       // 'tinggi' | 'hemat'
      kurangiAnimasi: false
    }
  };
}

function ambil() {
  try {
    const raw = localStorage.getItem(KEY_PROGRES);
    if (raw) return { ...defaultProgres(), ...JSON.parse(raw) };
  } catch {}

  // Migrasi ringan dari data versi sebelumnya (kalau ada), supaya progres lama tidak hilang
  const baru = defaultProgres();
  try {
    const lamaStats = JSON.parse(localStorage.getItem(KEY_PROGRES_LAMA) || 'null');
    if (lamaStats && lamaStats.percobaan) {
      baru.riwayatKuis.push({ tanggal: new Date().toISOString(), skor: lamaStats.skorTerbaik || 0, total: lamaStats.totalSoalTerakhir || 10 });
    }
    const lamaFavorit = JSON.parse(localStorage.getItem(KEY_FAVORIT_LAMA) || 'null');
    if (Array.isArray(lamaFavorit)) {
      lamaFavorit.forEach(k => { baru.stempelPlanet[k] = true; });
    }
  } catch {}
  simpan(baru);
  return baru;
}

function simpan(data) {
  try { localStorage.setItem(KEY_PROGRES, JSON.stringify(data)); } catch {}
}

export function getProgres() {
  return ambil();
}

export function tandaiSudahMulai() {
  const p = ambil();
  p.sudahMulai = true;
  simpan(p);
}

export function beriStempelPlanet(planetKey) {
  const p = ambil();
  p.stempelPlanet[planetKey] = true;
  simpan(p);
  evaluasiLencana(p);
  return p;
}

export function selesaikanMisi(misiId) {
  const p = ambil();
  const baruSelesai = !p.misiSelesai[misiId];
  p.misiSelesai[misiId] = true;
  simpan(p);
  evaluasiLencana(p);
  return { progres: p, baruSelesai };
}

export function jumlahMisiSelesai() {
  return Object.keys(ambil().misiSelesai).length;
}

export function jumlahPlanetDistempel() {
  return Object.keys(ambil().stempelPlanet).length;
}

export function catatHasilKuis(skor, total) {
  const p = ambil();
  p.riwayatKuis.unshift({ tanggal: new Date().toISOString(), skor, total });
  p.riwayatKuis = p.riwayatKuis.slice(0, 20); // simpan 20 riwayat terakhir saja
  simpan(p);
  return evaluasiLencana(p);
}

const DAFTAR_LENCANA = [
  { id: 'pemula', ikon: '🥉', nama: 'Pemula Antariksa', syarat: p => p.riwayatKuis.length >= 1 },
  { id: 'rajin', ikon: '🥈', nama: 'Penjelajah Rajin', syarat: p => p.riwayatKuis.length >= 3 },
  { id: 'gigih', ikon: '🥇', nama: 'Astronom Gigih', syarat: p => p.riwayatKuis.length >= 5 },
  { id: 'sempurna', ikon: '🏆', nama: 'Master Tata Surya', syarat: p => p.riwayatKuis.some(r => r.skor === r.total) },
  { id: 'penjelajah8', ikon: '🪐', nama: 'Penjelajah 8 Planet', syarat: p => Object.keys(p.stempelPlanet).length >= 8 },
  { id: 'misionaris', ikon: '🚀', nama: 'Penuntas Misi', syarat: p => Object.keys(p.misiSelesai).length >= 4 }
];

function evaluasiLencana(p) {
  const didapatSebelumnya = new Set(p.lencana);
  const semuaTerpenuhi = DAFTAR_LENCANA.filter(l => l.syarat(p));
  const baru = semuaTerpenuhi.filter(l => !didapatSebelumnya.has(l.id));
  p.lencana = semuaTerpenuhi.map(l => l.id);
  simpan(p);
  return { semua: semuaTerpenuhi, baru };
}

export function lencanaSaatIni() {
  const p = ambil();
  return DAFTAR_LENCANA.filter(l => p.lencana.includes(l.id));
}

export function semuaLencanaInfo() {
  return DAFTAR_LENCANA;
}

export function updatePengaturan(perubahan) {
  const p = ambil();
  p.pengaturan = { ...p.pengaturan, ...perubahan };
  simpan(p);
  return p.pengaturan;
}

export function getPengaturan() {
  return ambil().pengaturan;
}

export function daftarPlanetUtama() {
  return DAFTAR_PLANET_KEY;
}

// Evaluasi ulang lencana (dipanggil saat progres lain berubah, mis. stempel planet / misi)
export function evaluasiUlangLencana() {
  return evaluasiLencana(ambil());
}
