// ======  MODE PERBANDINGAN UKURAN PLANET  ======

// Data radius (km) dan warna kira-kira tiap planet, dipakai khusus untuk visualisasi ini.
const dataPlanet = [
  { key: 'Mercury', nama: 'Merkurius', radius: 2439.7, warna: '#a89f91' },
  { key: 'Venus', nama: 'Venus', radius: 6051.8, warna: '#e0c16c' },
  { key: 'Earth', nama: 'Bumi', radius: 6371, warna: '#3a86ff' },
  { key: 'Mars', nama: 'Mars', radius: 3389.5, warna: '#c1440e' },
  { key: 'Jupiter', nama: 'Yupiter', radius: 69911, warna: '#d9a066' },
  { key: 'Saturn', nama: 'Saturnus', radius: 58232, warna: '#e3c078' },
  { key: 'Uranus', nama: 'Uranus', radius: 25362, warna: '#8fd6e0' },
  { key: 'Neptune', nama: 'Neptunus', radius: 24622, warna: '#4266f5' },
  { key: 'Pluto', nama: 'Pluto', radius: 1188.3, warna: '#c9b8a8' }
];

const radiusTerbesar = Math.max(...dataPlanet.map(p => p.radius));
const UKURAN_MAKS_PX = 140; // ukuran lingkaran Yupiter (planet terbesar) di layar
const UKURAN_MIN_PX = 6;    // supaya planet terkecil tetap terlihat

function ukuranPx(radius) {
  const proporsi = radius / radiusTerbesar;
  return Math.max(UKURAN_MIN_PX, proporsi * UKURAN_MAKS_PX);
}

/**
 * Render layar perbandingan ukuran planet ke dalam `container`.
 * @param {HTMLElement} container
 */
export function initCompare(container) {
  container.innerHTML = `
    <div class="compare-header">
      <h1>📏 Perbandingan Ukuran Planet</h1>
      <p class="compare-sub">Digambar sesuai proporsi radius asli (skala relatif, bukan jarak sebenarnya)</p>
    </div>
    <div class="compare-visual" id="compare-visual"></div>
    <div class="compare-calc">
      <div class="compare-calc-row">
        <select id="compare-select-a" class="compare-select"></select>
        <span class="compare-vs">dibandingkan</span>
        <select id="compare-select-b" class="compare-select"></select>
      </div>
      <p class="compare-result" id="compare-result"></p>
    </div>
  `;

  const visual = container.querySelector('#compare-visual');
  dataPlanet.forEach(p => {
    const size = ukuranPx(p.radius);
    const el = document.createElement('div');
    el.className = 'compare-planet';
    el.innerHTML = `
      <div class="compare-circle" style="width:${size}px;height:${size}px;background:${p.warna};box-shadow:0 0 ${Math.max(6, size / 4)}px ${p.warna}55;"></div>
      <span class="compare-label">${p.nama}</span>
    `;
    visual.appendChild(el);
  });

  const selectA = container.querySelector('#compare-select-a');
  const selectB = container.querySelector('#compare-select-b');
  dataPlanet.forEach((p, i) => {
    selectA.innerHTML += `<option value="${i}">${p.nama}</option>`;
    selectB.innerHTML += `<option value="${i}">${p.nama}</option>`;
  });
  selectA.value = 2; // Bumi
  selectB.value = 4; // Yupiter

  function updateHasil() {
    const a = dataPlanet[Number(selectA.value)];
    const b = dataPlanet[Number(selectB.value)];
    const rasio = b.radius / a.radius;
    const resultEl = container.querySelector('#compare-result');

    if (a.key === b.key) {
      resultEl.textContent = `Itu planet yang sama 🙂 Pilih dua planet berbeda untuk membandingkan.`;
      return;
    }

    if (rasio >= 1) {
      resultEl.innerHTML = `<strong>${b.nama}</strong> memiliki radius sekitar <strong>${rasio.toFixed(1)}×</strong> lebih besar dari <strong>${a.nama}</strong>.`;
    } else {
      resultEl.innerHTML = `<strong>${b.nama}</strong> memiliki radius sekitar <strong>${(1 / rasio).toFixed(1)}×</strong> lebih kecil dari <strong>${a.nama}</strong>.`;
    }
  }

  selectA.addEventListener('change', updateHasil);
  selectB.addEventListener('change', updateHasil);
  updateHasil();
}
