// Reset only this app's learning data; never clear unrelated origin storage.
const LEARNING_KEYS = ['zepto_v1', 'progresAstronaut_v2', 'kuisStats', 'planetFavorit'];
export function resetLearning(storage = localStorage) {
  const before = new Map(LEARNING_KEYS.map(key => [key, storage.getItem(key)]));
  let settings;
  try { settings = JSON.parse(before.get('progresAstronaut_v2') || '{}')?.pengaturan; } catch {}
  try {
    for (const key of LEARNING_KEYS) storage.removeItem(key);
    if (settings && typeof settings === 'object') {
      storage.setItem('progresAstronaut_v2', JSON.stringify({pengaturan: settings}));
    }
  } catch (error) {
    // Best effort rollback if browser storage is unavailable.
    for (const [key, value] of before) {
      try { if (value === null) storage.removeItem(key); else storage.setItem(key, value); } catch {}
    }
    throw error;
  }
}
export function initReset({stopAudio, reload = () => window.location.reload()}) {
  const dialog = document.getElementById('z-reset-dialog');
  const confirm = document.getElementById('z-reset-confirm');
  const error = document.getElementById('z-reset-error');
  const open = () => { error.hidden = true; confirm.disabled = false; if (!dialog.open) dialog.showModal(); };
  document.getElementById('btn-reset-belajar').addEventListener('click', open);
  window.addEventListener('zepto-request-reset', open);
  document.getElementById('z-reset-cancel').addEventListener('click', () => dialog.close());
  confirm.addEventListener('click', async () => {
    confirm.disabled = true;
    try {
      resetLearning();
      window.dispatchEvent(new Event('zepto-navigation'));
      window.dispatchEvent(new Event('zepto-leave-solar'));
      try { await stopAudio(); } catch {}
      reload(); // Also cancels in-memory timers and resets the 3D scene.
    } catch {
      confirm.disabled = false;
      error.textContent = 'Reset belum berhasil karena penyimpanan perangkat tidak tersedia. Coba lagi.';
      error.hidden = false;
    }
  });
}
